insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('lunch-break-actually-taken-log', 'Lunch Break Actually Taken Log', 'worksheet'::resource_kind, 'A two-week log of whether the client took a real break at midday, and what happened when they did or did not.', 'Use it to make the skipped lunch break visible and test what a taken one changes in the afternoon.', array['Adults']::text[], 'Two weeks, two minutes a day', 'Many clients who report afternoon irritability or evening exhaustion eat at their desk or skip the break entirely. Ask them to log each workday: was a break taken, for how long, away from the screen or not, and a quick afternoon energy rating. Do not dictate what the break should be; the point is the record. In session, lay the two weeks side by side and let the client draw the comparison. Watch for the belief that stopping is a luxury the job does not allow, and test it against what the record shows.', '[{"id": "f0", "type": "textarea", "label": "Day and whether I took a break, how long, and whether I left my desk or screen:"}, {"id": "f1", "type": "textarea", "label": "My energy and mood in the late afternoon, 1 to 10:"}, {"id": "f2", "type": "textarea", "label": "What got in the way on the days I skipped it:"}, {"id": "f3", "type": "textarea", "label": "What I did with the break on the days I took one:"}, {"id": "f4", "type": "textarea", "label": "What the two weeks seem to say about breaks and my afternoons:"}]'::jsonb, array['self-monitoring', 'routines', 'work']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('week-subtraction-list-page', 'Week Subtraction List Page', 'worksheet'::resource_kind, 'A planning page that starts from what the client will drop from the coming week, not what they will add.', 'Use it to relieve an overloaded week by removing commitments before any new plan is made.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients arriving overloaded often leave session with more to do. This page reverses the usual move: before any goal is set, the client lists everything on the coming week and chooses at least three items to cancel, shrink, delegate or postpone. Have them write the actual sentence they will say to cancel each one, because the planning is easy and the saying is hard. Watch for items the client claims cannot move; ask what would happen if it did, and whether that outcome is real or feared. Review next session what was actually removed.', '[{"id": "f0", "type": "textarea", "label": "Everything already on my week, including the small things:"}, {"id": "f1", "type": "textarea", "label": "Three or more items I will cancel, shrink, hand off or move:"}, {"id": "f2", "type": "textarea", "label": "The exact words I will use to cancel or move each one:"}, {"id": "f3", "type": "textarea", "label": "What I expect to feel after saying them, and what I expect the other person to say:"}, {"id": "f4", "type": "textarea", "label": "What I will do with the time that opens up, or whether I will leave it empty:"}]'::jsonb, array['planning', 'boundaries', 'overwhelm']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('doctor-visit-question-list-prep-sheet', 'Doctor Visit Question List Prep Sheet', 'worksheet'::resource_kind, 'A one-page sheet for writing down the questions and facts a client wants to bring to a medical appointment.', 'Use it to help a client leave a medical visit with their questions asked instead of remembered in the parking lot.', array['Adults', 'Teens']::text[], '15 minutes before the appointment', 'Clients who freeze in medical settings, or who minimize what they are feeling in front of a clinician, often come out having asked nothing. Fill this sheet in session before the visit: the three questions that matter most in priority order, the facts about their situation they tend to leave out, and what they want to happen if they are told there is no time. Rehearse saying the first question aloud. Encourage them to hand the sheet over if speaking is hard. Afterward, review which questions got asked and which did not, and why.', '[{"id": "f0", "type": "textarea", "label": "The appointment, who it is with, and what it is about:"}, {"id": "f1", "type": "textarea", "label": "My three most important questions, in order:"}, {"id": "f2", "type": "textarea", "label": "Things about how I have been doing that I tend to leave out or downplay:"}, {"id": "f3", "type": "textarea", "label": "What I will say if I feel rushed or interrupted:"}, {"id": "f4", "type": "textarea", "label": "Who is coming with me, if anyone, and what I want them to do:"}, {"id": "f5", "type": "textarea", "label": "Afterward: which questions I asked, and what I did not get to ask:"}]'::jsonb, array['planning', 'health', 'self-advocacy']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('promises-to-others-follow-through-sheet', 'Promises to Others Follow-Through Sheet', 'worksheet'::resource_kind, 'A tracker for the small things the client has told other people they would do, and whether each one happened.', 'Use it to close the gap between what a client says yes to and what they actually deliver.', array['Adults', 'Teens']::text[], 'One week', 'Clients who feel chronically guilty in their relationships often carry a cloud of half-remembered commitments: the link they said they would send, the call they said they would return. Have them list every promise made this week, however small, who it was to, and by when. At week end, mark each as kept, late or dropped. The pattern matters more than any single item: are they overpromising in the moment to please, forgetting, or avoiding? Decide together whether the fix is saying yes less, writing things down, or a direct message when something will be late.', '[{"id": "f0", "type": "textarea", "label": "Promises I made this week, who to, and by when:"}, {"id": "f1", "type": "textarea", "label": "Which ones I kept, which were late, and which I dropped:"}, {"id": "f2", "type": "textarea", "label": "What was happening in the moment I said yes to the ones that slipped:"}, {"id": "f3", "type": "textarea", "label": "What I told myself about the other person when I noticed I had not done it:"}, {"id": "f4", "type": "textarea", "label": "One change for next week: fewer yeses, a written list, or an honest message when I am late:"}]'::jsonb, array['self-monitoring', 'communication', 'planning']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('snooze-button-count-and-wake-plan-log', 'Snooze Button Count and Wake Plan Log', 'worksheet'::resource_kind, 'A morning log of how many times the alarm was snoozed and what the first ten minutes awake actually held.', 'Use it to turn a fuzzy complaint about mornings into a countable habit the client can experiment with.', array['Adults', 'Teens']::text[], 'One week', 'Clients often say mornings are a disaster without being able to say what happens in them. For one week, have them count the snoozes, note the time they actually got vertical, and write one line about the first ten minutes. In session, look for what the snoozing buys them: more sleep, a delay before a dreaded day, or simple habit. Then design a tiny experiment for the following week, such as the alarm across the room or one planned thing to look forward to in the first ten minutes. Avoid a lecture on sleep; the client already knows.', '[{"id": "f0", "type": "textarea", "label": "Each morning: alarm time, number of snoozes, and the time I actually got up:"}, {"id": "f1", "type": "textarea", "label": "What the first ten minutes awake held:"}, {"id": "f2", "type": "textarea", "label": "What the extra snoozes seemed to be for on the days there were many:"}, {"id": "f3", "type": "textarea", "label": "What I dread or look forward to on waking, honestly:"}, {"id": "f4", "type": "textarea", "label": "One small experiment for next week’s mornings:"}]'::jsonb, array['self-monitoring', 'routines', 'sleep']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('externalization-of-voices-role-play-sheet', 'Externalization of Voices Role Play Sheet', 'cbt'::resource_kind, 'A role-play sheet where the clinician voices the client’s negative thoughts in the second person and the client answers back.', 'Use it to let the client hear their self-talk from the outside and practice replying to it out loud.', array['Adults', 'Teens']::text[], '30 minutes in session', 'Write the client’s hot thoughts on the sheet, then say each one to them as an accusation in the second person: you always mess things up. The client answers in the first person with a reply that is both honest and fair. If they get stuck or cave, swap roles so you model a reply and they play the critic, then swap back. Keep going until the client has a reply they believe for each line, and have them write it down. This works best once a client has a few balanced thoughts already; it falls flat when the reply is simply a positive slogan.', '[{"id": "f0", "type": "textarea", "label": "The negative thoughts I want to hear said to me, written as you statements:"}, {"id": "f1", "type": "textarea", "label": "My first reply to each one, before we practiced:"}, {"id": "f2", "type": "textarea", "label": "The reply that landed best for each one after we swapped roles:"}, {"id": "f3", "type": "textarea", "label": "How it felt to hear the thought in someone else’s voice:"}, {"id": "f4", "type": "textarea", "label": "The reply I want to keep on a card for the week:"}]'::jsonb, array['core CBT', 'thinking traps', 'self-esteem']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('hour-by-hour-versus-headline-day-rating-sheet', 'Hour by Hour Versus Headline Day Rating Sheet', 'cbt'::resource_kind, 'A sheet comparing the client’s one-word verdict on a day with an hour-by-hour rating of the same day.', 'Use it to show a client how a day’s headline is written by its worst hour and test whether the detail agrees.', array['Adults', 'Teens']::text[], '15 minutes each evening for several days', 'At the end of the day the client writes the headline first, a single word or line summing it up, then rates each waking hour 1 to 10 without looking back at the headline. Most clients find the hours average well above the headline, and that one or two hours wrote the whole story. Do this for at least four days before drawing conclusions. In session, name the pattern as a filter rather than a lie, and ask what headline the hours would have written on their own. Useful with low mood and with perfectionism alike.', '[{"id": "f0", "type": "textarea", "label": "Today’s headline, in one word or one line, written first:"}, {"id": "f1", "type": "textarea", "label": "Each waking hour rated 1 to 10, with a word about what was happening:"}, {"id": "f2", "type": "textarea", "label": "The average of the hours, roughly, next to the headline:"}, {"id": "f3", "type": "textarea", "label": "Which hour or hours wrote the headline:"}, {"id": "f4", "type": "textarea", "label": "The headline the hours would have written on their own:"}]'::jsonb, array['core CBT', 'thinking traps', 'self-monitoring']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('other-shoe-to-drop-thought-record', 'Other Shoe to Drop Thought Record', 'cbt'::resource_kind, 'A thought record for the moment something goes well and the client’s mind announces that disaster must follow.', 'Use it to catch the belief that good news is a setup and test it against what actually followed.', array['Adults', 'Teens']::text[], '10 minutes whenever good news arrives, over several weeks', 'Ask the client to open this record when something good happens and the dread arrives behind it. They write the good event, the prediction about what it will cost, and a confidence rating. The second half is filled in a week later: what actually followed. Over several entries the client builds their own record of how often the shoe dropped, which beats any reassurance from you. Watch for the client discounting the good event itself; keep the first column factual. If a shoe did drop, record it honestly and look at whether it was connected to the good news at all.', '[{"id": "f0", "type": "textarea", "label": "The good thing that happened:"}, {"id": "f1", "type": "textarea", "label": "What my mind said would follow, and how sure I was, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What I did in response: braced, downplayed, told no one, or something else:"}, {"id": "f3", "type": "textarea", "label": "One week later: what actually followed:"}, {"id": "f4", "type": "textarea", "label": "Whether what followed had anything to do with the good news:"}, {"id": "f5", "type": "textarea", "label": "My running tally of shoes predicted versus shoes dropped:"}]'::jsonb, array['core CBT', 'thinking traps', 'behavioral experiment']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('always-and-never-word-count-sheet', 'Always and Never Word Count Sheet', 'cbt'::resource_kind, 'A tally sheet for the absolute words in a client’s self-talk and a space to rewrite each one with a real frequency.', 'Use it to help a client hear how often they speak in always and never and replace each with what is actually true.', array['Adults', 'Teens']::text[], 'Three days of tallying, then 20 minutes in session', 'Give the client a short list of absolute words: always, never, everyone, no one, every time, nothing. For three days they tally each time one shows up in their thoughts or speech about themselves, with a note of the sentence. In session, pick the five most frequent sentences and ask for the real number: how many times out of the last ten. Rewrite each with the honest frequency, which is almost never zero or always. The rewritten sentence often has less sting without being falsely positive. Teens enjoy keeping score; adults may need permission to tally only in thought.', '[{"id": "f0", "type": "textarea", "label": "My tally of always, never, everyone, no one, every time and nothing over three days:"}, {"id": "f1", "type": "textarea", "label": "The five sentences that came up most:"}, {"id": "f2", "type": "textarea", "label": "For each one, how many times out of the last ten it was actually true:"}, {"id": "f3", "type": "textarea", "label": "Each sentence rewritten with the real frequency:"}, {"id": "f4", "type": "textarea", "label": "How the rewritten sentences feel compared with the originals:"}]'::jsonb, array['core CBT', 'thinking traps', 'overgeneralization']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('ask-instead-of-assume-clarification-experiment-sheet', 'Ask Instead of Assume Clarification Experiment Sheet', 'cbt'::resource_kind, 'An experiment sheet for replacing a guess about what someone meant with a direct clarifying question.', 'Use it to test whether asking what someone meant goes as badly as the client predicts, and what it reveals.', array['Adults', 'Teens']::text[], 'One week', 'Clients who mind-read fill ambiguous moments with the worst interpretation and then act on it. Have them pick a low-stakes relationship and, three times this week, ask a clarifying question instead of assuming: did you mean this, or something else? They predict beforehand how the person will react and what the answer will be. Afterward they record what was actually said. The usual finding is that the assumed meaning was wrong more often than right and that asking cost little. Keep the first targets safe; save the boss or the parent for later rounds.', '[{"id": "f0", "type": "textarea", "label": "The ambiguous moment: what they said or did, and what I assumed it meant:"}, {"id": "f1", "type": "textarea", "label": "My prediction: how they will react to being asked, and what the answer will be:"}, {"id": "f2", "type": "textarea", "label": "The clarifying question I asked, word for word:"}, {"id": "f3", "type": "textarea", "label": "What they actually said:"}, {"id": "f4", "type": "textarea", "label": "How close my assumption was, and how asking felt compared with guessing:"}, {"id": "f5", "type": "textarea", "label": "What I will ask about next time instead of assuming:"}]'::jsonb, array['core CBT', 'behavioral experiment', 'communication']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('feeding-the-tiger-metaphor-page', 'Feeding the Tiger Metaphor Page', 'act'::resource_kind, 'A metaphor page about the anxiety tiger that grows each time it is fed with avoidance.', 'Use it to help a client see that every escape quiets the tiger today and makes it bigger tomorrow.', array['Adults', 'Teens']::text[], '20 minutes', 'Tell the story: a small tiger cub growls, and the client throws it meat to quiet it. It works, and the tiger grows, and next time it takes more. Then have the client name their tiger and list the meat: every avoidance, reassurance, cancellation or checking that quiets it. Ask what size the tiger is now compared with a year ago. The move is not to fight the tiger but to stop feeding it and let it shrink back, which means tolerating the growl. Follow with a willingness exercise or a small step. Children and teens may want to draw the tiger at both sizes.', '[{"id": "f0", "type": "textarea", "label": "What my tiger growls about:"}, {"id": "f1", "type": "textarea", "label": "The meat I feed it: what I do to make the growl stop:"}, {"id": "f2", "type": "textarea", "label": "How big the tiger is now compared with a year ago:"}, {"id": "f3", "type": "textarea", "label": "What it would mean to hear the growl and not feed it, in one real situation:"}, {"id": "f4", "type": "textarea", "label": "The first small meal I am willing to skip this week:"}]'::jsonb, array['core ACT', 'willingness', 'avoidance']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('thoughts-as-subtitles-defusion-page', 'Thoughts as Subtitles Defusion Page', 'act'::resource_kind, 'A defusion exercise that treats running thoughts as subtitles on a screen rather than as the scene itself.', 'Use it to give a client a way to notice commentary as commentary while the actual moment keeps playing.', array['Adults', 'Teens']::text[], '10 minutes, then daily practice', 'Invite the client to picture their life as a film with subtitles running along the bottom. The subtitles are the mind’s commentary: this is going badly, they think you are strange. Practice in session by having them describe the room while reading aloud the subtitles that appear, in a flat announcer voice. The scene and the subtitles are two different things, and the client is the one watching both. For homework they practice noticing a subtitle during one ordinary activity a day and saying, silently, subtitle.', '[{"id": "f0", "type": "textarea", "label": "The subtitles that run most often during my day:"}, {"id": "f1", "type": "textarea", "label": "A moment this week where I noticed the subtitle and the scene were different things:"}, {"id": "f2", "type": "textarea", "label": "What the scene actually contained once I looked past the subtitle:"}, {"id": "f3", "type": "textarea", "label": "What changed when I read the subtitle in an announcer voice:"}, {"id": "f4", "type": "textarea", "label": "The activity I will practice this with every day:"}]'::jsonb, array['core ACT', 'defusion', 'mindfulness']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('bad-cup-descriptions-versus-evaluations-page', 'Bad Cup Descriptions Versus Evaluations Page', 'act'::resource_kind, 'An exercise that separates what can be described about a thing from the judgments the mind adds to it.', 'Use it to help a client notice that bad, ugly and worthless live in the evaluation, not in the object or the person.', array['Adults', 'Teens']::text[], '20 minutes', 'Hold up a cup and ask the client to describe it: ceramic, white, chipped. Then ask whether it is a good cup. Point out that chipped stays true when everyone leaves the room, and good or bad does not. Then move to a judgment the client makes about themselves and sort it into the two columns: what could a camera record, and what is the mind adding. Clients often discover that almost all of a painful self-statement is in the second column. This is not an argument that the evaluation is wrong, only that it is an evaluation. Keep the tone curious rather than corrective.', '[{"id": "f0", "type": "textarea", "label": "The cup, described as a camera would record it:"}, {"id": "f1", "type": "textarea", "label": "The judgments my mind adds to the cup:"}, {"id": "f2", "type": "textarea", "label": "A painful statement about myself that I want to sort:"}, {"id": "f3", "type": "textarea", "label": "What a camera would record about me in that statement:"}, {"id": "f4", "type": "textarea", "label": "What my mind adds, and how it feels to see that in its own column:"}]'::jsonb, array['core ACT', 'defusion', 'self-esteem']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('two-scales-discomfort-and-willingness-page', 'Two Scales Discomfort and Willingness Page', 'act'::resource_kind, 'A page with two dials, one for discomfort and one for willingness, to show which one the client can actually turn.', 'Use it to shift a client’s effort from lowering discomfort to raising willingness in a chosen situation.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw two dials. The first is discomfort, 0 to 10, and the client marks where it sits in the situation they are stuck on. Ask how much effort has gone into turning that dial down and how well it has worked. The second is willingness, 0 to 10, and the client marks where it sits now. Point out that the second dial has a handle and the first does not. Explore what a one-point rise in willingness would look like in behavior this week. Clients often expect willingness to mean liking it; clarify that it means allowing the first dial to read what it reads while they move.', '[{"id": "f0", "type": "textarea", "label": "The situation I am stuck on:"}, {"id": "f1", "type": "textarea", "label": "Where my discomfort dial sits there, 0 to 10, and what I have done to turn it down:"}, {"id": "f2", "type": "textarea", "label": "How well turning it down has worked, honestly:"}, {"id": "f3", "type": "textarea", "label": "Where my willingness dial sits now, 0 to 10:"}, {"id": "f4", "type": "textarea", "label": "What one point higher on the willingness dial would look like in what I do this week:"}]'::jsonb, array['core ACT', 'willingness', 'acceptance']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('emotion-function-three-jobs-sheet', 'Emotion Function Three Jobs Sheet', 'dbt'::resource_kind, 'A sheet that walks a client through the three jobs an emotion does: communicating, motivating and self-validating.', 'Use it to help a client see what a painful emotion is for before deciding whether to change it.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'From the emotion regulation module: emotions communicate to others, organize and motivate action, and tell us something about the situation. Pick a recent strong emotion and walk the client through each job. What did the face and voice tell other people? What did the body get ready to do? What was the emotion saying about what mattered? Clients who want to delete an emotion usually soften once they can name its job. Finish by asking whether the emotion fit the facts and whether acting on it would be effective, which sets up check the facts or opposite action.', '[{"id": "f0", "type": "textarea", "label": "The emotion, where I was, and what set it off:"}, {"id": "f1", "type": "textarea", "label": "What my face, voice and posture told the people around me:"}, {"id": "f2", "type": "textarea", "label": "What my body got ready to do, and what I actually did:"}, {"id": "f3", "type": "textarea", "label": "What the emotion was telling me about the situation and what matters to me:"}, {"id": "f4", "type": "textarea", "label": "Whether the emotion fit the facts, and whether acting on it would have worked:"}]'::jsonb, array['core DBT', 'emotion regulation', 'emotion identification']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('primary-and-secondary-emotion-layers-sheet', 'Primary and Secondary Emotion Layers Sheet', 'dbt'::resource_kind, 'A layering sheet that separates the first emotion in a moment from the emotions the client then had about having it.', 'Use it to help a client find the primary emotion under the shame, anger or anxiety stacked on top of it.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw two layers. The bottom is the first emotion, the one that arrived in response to the event: sadness, fear, hurt. The top is the emotions that arrived in response to the first one: shame for crying, anger at being afraid, anxiety about being sad. Many clients only know the top layer. Walk back to the event and ask what a camera would have caught in the first two seconds. Secondary emotions usually come with a judgment attached; write it down. The primary emotion is often easier to validate and to act on effectively, and the secondary one quiets when the first is named.', '[{"id": "f0", "type": "textarea", "label": "The event, briefly:"}, {"id": "f1", "type": "textarea", "label": "The first emotion that arrived, what my body did in the first seconds:"}, {"id": "f2", "type": "textarea", "label": "The emotion I then had about having that emotion:"}, {"id": "f3", "type": "textarea", "label": "The judgment that came with the second layer:"}, {"id": "f4", "type": "textarea", "label": "What the first emotion needed, and what the second one was trying to do:"}, {"id": "f5", "type": "textarea", "label": "A validating sentence for the first emotion:"}]'::jsonb, array['core DBT', 'emotion regulation', 'self-validation']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('stone-flake-on-the-lake-wise-mind-card', 'Stone Flake on the Lake Wise Mind Card', 'dbt'::resource_kind, 'A guided imagery card for settling into wise mind by sinking slowly like a stone flake to the bottom of a lake.', 'Use it to give a client a brief imagery practice for finding a calm center when emotion mind is loud.', array['Adults', 'Teens', 'Groups']::text[], 'Five minutes, daily', 'Read the imagery slowly: a clear lake on a sunny day, and you are a small flake of stone, light and flat, released on the surface and drifting down through the cool water, settling at last on the still sand at the bottom. Attend to what it is like to be there, at the center, where the water is calm even if the surface is ruffled. Practice in session first, then as a daily five minutes. Clients who dislike water imagery can use a feather settling in a quiet room. Ask afterward for the sensations that marked arriving, so they can recognize wise mind by feel.', '[{"id": "f0", "type": "textarea", "label": "The sensations I noticed as the flake drifted down:"}, {"id": "f1", "type": "textarea", "label": "What it was like at the bottom, at the center:"}, {"id": "f2", "type": "textarea", "label": "How my body told me I had arrived in a calmer place:"}, {"id": "f3", "type": "textarea", "label": "A decision I would like to take to the bottom of the lake this week:"}, {"id": "f4", "type": "textarea", "label": "When in my day I will practice the five minutes:"}]'::jsonb, array['core DBT', 'mindfulness', 'wise mind']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('spiral-staircase-into-wise-mind-card', 'Spiral Staircase Into Wise Mind Card', 'dbt'::resource_kind, 'An imagery card for walking slowly down a spiral staircase inside oneself to the quiet level where wise mind sits.', 'Use it to give a client a step-by-step imagery route into wise mind when they need to decide something.', array['Adults', 'Teens', 'Groups']::text[], 'Five to ten minutes', 'Guide the client to picture a spiral staircase descending inside them. They walk down slowly, one step at a time, resting on each landing to notice what is there. If it is dark, they can imagine a light; if a step feels unsafe, they may pause as long as they need. They go only as deep as feels right today, and at the bottom they sit and ask their question. Debrief the images and the body sensations, since those become the client’s own map back. Some clients prefer to go up a staircase; let them. Do not rush the descent, and keep the question for the bottom.', '[{"id": "f0", "type": "textarea", "label": "What the staircase looked like, and what I noticed on the landings:"}, {"id": "f1", "type": "textarea", "label": "How deep I went today, and what told me to stop there:"}, {"id": "f2", "type": "textarea", "label": "The question I asked at the bottom:"}, {"id": "f3", "type": "textarea", "label": "What came back, in words or in a feeling:"}, {"id": "f4", "type": "textarea", "label": "What I will remember about the route so I can go again:"}]'::jsonb, array['core DBT', 'mindfulness', 'wise mind']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('shaping-myself-small-steps-reinforcement-sheet', 'Shaping Myself Small Steps Reinforcement Sheet', 'dbt'::resource_kind, 'A sheet for breaking a wanted behavior into steps the client can actually do today and rewarding each one.', 'Use it to apply shaping to the client’s own behavior change instead of waiting for the finished version.', array['Adults', 'Teens']::text[], '20 minutes, then one week', 'Shaping means reinforcing small approximations instead of waiting for the whole behavior. Pick one thing the client wants to do more of and write the finished version at the top. Then work backward to a first step so small it is almost silly, and three or four steps between. Attach a reinforcer to each that arrives right away, not at the end of the week. Watch for clients who feel rewarding themselves is childish or that only the full behavior counts; that belief is often why the behavior never started. Review the week and raise the step only when the current one is easy.', '[{"id": "f0", "type": "textarea", "label": "The finished behavior I want, described so I would know it if I saw it:"}, {"id": "f1", "type": "textarea", "label": "The smallest first step, so small I could do it today:"}, {"id": "f2", "type": "textarea", "label": "Three or four steps between the first step and the finished version:"}, {"id": "f3", "type": "textarea", "label": "What I will give myself right after each step, and when:"}, {"id": "f4", "type": "textarea", "label": "This week: which steps happened, and when the current step started to feel easy:"}]'::jsonb, array['core DBT', 'behavior change', 'skills']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('what-makes-us-laugh-inventory-for-partners', 'What Makes Us Laugh Inventory for Partners', 'couples'::resource_kind, 'An inventory each partner fills in about what has made them laugh together, then compares with the other.', 'Use it to help a couple in a serious season find and rebuild the shared humor they used to have.', array['Couples']::text[], '30 minutes', 'Couples deep in logistics or conflict often report that they have stopped laughing together, and neither can say when. Each partner separately lists the times they remember laughing together, the shows or jokes or people that did it, and the kind of humor they each enjoy. Then they compare. The lists are usually longer than expected and often overlap in surprising places. Finish with one concrete plan to put something from the overlap into the next two weeks. Watch for one partner’s humor landing as teasing to the other; name it plainly and sort it into a separate box.', '[{"id": "f0", "type": "textarea", "label": "Partner A: times I remember us laughing together, and what set it off:"}, {"id": "f1", "type": "textarea", "label": "Partner B: times I remember us laughing together, and what set it off:"}, {"id": "f2", "type": "textarea", "label": "Partner A: the kind of humor I enjoy most, and the kind that stings:"}, {"id": "f3", "type": "textarea", "label": "Partner B: the kind of humor I enjoy most, and the kind that stings:"}, {"id": "f4", "type": "textarea", "label": "Where our lists overlap:"}, {"id": "f5", "type": "textarea", "label": "One thing from the overlap we will put into the next two weeks:"}]'::jsonb, array['couples', 'connection', 'play']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('how-we-met-retelling-interview-for-partners', 'How We Met Retelling Interview for Partners', 'couples'::resource_kind, 'A structured interview where each partner tells the story of how they met and what they first noticed in the other.', 'Use it to bring a couple’s origin story into the room and listen for the warmth or the strain in how they tell it.', array['Couples']::text[], '40 minutes in session', 'Ask one partner to tell the meeting story while the other listens without correcting, then swap. Follow with the questions on the sheet: what did you first notice, what made you want a second meeting, what did your friends say. How a couple tells this story tends to reflect how they are doing now, so listen for fondness, for we-ness, and for cynicism or rewriting. Afterward ask each what they heard in the other’s version that they had forgotten. Do not force a happy ending; if the telling is flat, that is data to hold gently and come back to.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how we met, as I remember it, and what I first noticed:"}, {"id": "f1", "type": "textarea", "label": "Partner B: how we met, as I remember it, and what I first noticed:"}, {"id": "f2", "type": "textarea", "label": "Partner A: what made me want to see them again:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what made me want to see them again:"}, {"id": "f4", "type": "textarea", "label": "Something I heard in my partner’s version that I had forgotten or never knew:"}, {"id": "f5", "type": "textarea", "label": "What the two versions tell us about who we were then and who we are now:"}]'::jsonb, array['couples', 'Gottman', 'connection']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('family-culture-we-are-building-sheet-for-partners', 'Family Culture We Are Building Sheet for Partners', 'couples'::resource_kind, 'A sheet where partners each describe the family culture they came from and the one they want to build together.', 'Use it to surface the unspoken inheritances each partner brought and choose deliberately what to keep.', array['Couples']::text[], '45 minutes', 'Each partner answers separately: how did your family handle money, anger, holidays, apologies, affection and chores, and what did nobody ever say out loud? Then they share and mark each item keep, change or decide later. Many recurring fights turn out to be two inherited rules colliding with neither partner knowing they had one. Keep the tone anthropological rather than blaming; the families are not on trial. End with three sentences that begin In our family, we, written together. Revisit the sheet when a new stage arrives, such as a child or a move.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how my family handled money, anger, holidays, apologies, affection and chores:"}, {"id": "f1", "type": "textarea", "label": "Partner B: how my family handled money, anger, holidays, apologies, affection and chores:"}, {"id": "f2", "type": "textarea", "label": "Partner A: the rules nobody said out loud, as I understand them now:"}, {"id": "f3", "type": "textarea", "label": "Partner B: the rules nobody said out loud, as I understand them now:"}, {"id": "f4", "type": "textarea", "label": "Which inherited rules we will keep, which we will change, and which we will decide later:"}, {"id": "f5", "type": "textarea", "label": "Three sentences that begin In our family, we:"}]'::jsonb, array['couples', 'family', 'values']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('childhood-home-rules-interview-for-partners', 'Childhood Home Rules Interview for Partners', 'couples'::resource_kind, 'A partner interview about the everyday rules of each childhood home, from dinner time to how doors were closed.', 'Use it to help partners understand that a habit that irritates them is often a rule the other grew up inside.', array['Couples']::text[], '30 minutes', 'Partners interview each other with the questions on the sheet: what time was dinner, who cooked, were doors open or shut, how loud was normal, what happened when someone was sick, how were birthdays done. The interviewer only asks and writes; no commentary. Then each names one current irritation that now makes more sense. This is lighter than a full family history and works early in couples work. Watch for a partner whose childhood home was unsafe; let them answer selectively and move on, and come back to it in a different frame if needed.', '[{"id": "f0", "type": "textarea", "label": "Partner A: dinner time, who cooked, doors, noise level, sick days, birthdays, bedtimes in my childhood home:"}, {"id": "f1", "type": "textarea", "label": "Partner B: dinner time, who cooked, doors, noise level, sick days, birthdays, bedtimes in my childhood home:"}, {"id": "f2", "type": "textarea", "label": "Partner A: one thing my partner does that makes more sense now:"}, {"id": "f3", "type": "textarea", "label": "Partner B: one thing my partner does that makes more sense now:"}, {"id": "f4", "type": "textarea", "label": "One household rule of our own we want to settle this month:"}]'::jsonb, array['couples', 'family', 'communication']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('ideal-saturday-side-by-side-sheet-for-partners', 'Ideal Saturday Side by Side Sheet for Partners', 'couples'::resource_kind, 'Each partner writes their ideal Saturday hour by hour, then the two are laid side by side to find the overlaps and the clashes.', 'Use it to show a couple where their pictures of a good day off agree and where they have been silently colliding.', array['Couples']::text[], '30 minutes', 'Each partner fills in a Saturday from waking to bed exactly as they would want it if the other had no veto, including alone time, chores, people and screens. Lay the two columns side by side. Overlaps are easy wins; clashes are usually the source of the Saturday morning argument neither could explain. Negotiate one actual Saturday that gives each partner the hour that matters most to them, rather than an average that satisfies nobody. Return the following week to review how it went. Useful for couples with young children, where the day off has quietly vanished.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my ideal Saturday, hour by hour, with no veto from anyone:"}, {"id": "f1", "type": "textarea", "label": "Partner B: my ideal Saturday, hour by hour, with no veto from anyone:"}, {"id": "f2", "type": "textarea", "label": "Where our two Saturdays overlap:"}, {"id": "f3", "type": "textarea", "label": "Where they clash, and which clash we have been arguing about without naming it:"}, {"id": "f4", "type": "textarea", "label": "The one hour that matters most to each of us:"}, {"id": "f5", "type": "textarea", "label": "Our plan for the next real Saturday, with both of those hours in it:"}]'::jsonb, array['couples', 'planning', 'connection']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('lazy-eight-breathing-trace-board-craft', 'Lazy Eight Breathing Trace Board Craft', 'kids'::resource_kind, 'A child decorates a large sideways figure eight and traces it with a finger, breathing in on one loop and out on the other.', 'Use it to give a child a breathing practice they can see and touch, with a parent tracing alongside.', array['Children']::text[], '20 minutes to make, one minute to use', 'Draw a large sideways eight on card and let the child decorate the two loops in two colors, with a star where the loops cross. To use it, the finger starts at the star, traces one loop while breathing in, passes the star, and traces the other while breathing out. Show the parent how to trace a second board beside the child rather than instructing, and to use it at calm times first so it is familiar when big feelings come. Children who find breathing exercises boring often accept this one because the hand is busy. Keep the board somewhere the child can reach it.', '[{"id": "f0", "type": "textarea", "label": "The colors I picked for the breathe-in loop and the breathe-out loop:"}, {"id": "f1", "type": "textarea", "label": "How many times around the eight before I feel slower:"}, {"id": "f2", "type": "textarea", "label": "Where my board lives at home:"}, {"id": "f3", "type": "textarea", "label": "A time this week I used it, and who traced with me:"}, {"id": "f4", "type": "textarea", "label": "Parent: when we practiced at a calm time, and what I noticed:"}]'::jsonb, array['children', 'grounding', 'craft']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('scary-dream-catcher-craft', 'Scary Dream Catcher Craft', 'kids'::resource_kind, 'A child builds a hoop with yarn and ribbons to hang near the bed, with a plan for what happens after a scary dream.', 'Use it to give a child a comforting bedtime object and a parent a simple shared plan for the middle of the night.', array['Children']::text[], '30 minutes to make', 'Bend a paper plate rim or an embroidery hoop, string yarn across it, and let the child add ribbons, beads and a drawing of something that makes them feel safe. While crafting, talk about what dreams are and agree on the after-a-dream plan on the sheet: what the child does, what the parent does, and the words they will say. Be clear with the child that the catcher is a comfort object rather than magic, so it does not become something that must work. Some cultures hold the dream catcher as sacred; if that matters to the family, make a simple comfort mobile instead.', '[{"id": "f0", "type": "textarea", "label": "What I put on my catcher and the safe thing I drew:"}, {"id": "f1", "type": "textarea", "label": "What I will do first if a scary dream wakes me up:"}, {"id": "f2", "type": "textarea", "label": "What my grown-up will do, and the words they will say:"}, {"id": "f3", "type": "textarea", "label": "Something I can think about or hold until I feel sleepy again:"}, {"id": "f4", "type": "textarea", "label": "Parent: how the plan went this week, and what we changed:"}]'::jsonb, array['children', 'sleep', 'craft']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('robot-and-rag-doll-tense-and-floppy-play', 'Robot and Rag Doll Tense and Floppy Play', 'kids'::resource_kind, 'A movement game where the child stiffens like a robot on one cue and goes floppy like a rag doll on the next.', 'Use it to teach a child the difference between a tight body and a loose one so they can choose loose when upset.', array['Children']::text[], '10 minutes, repeated at home', 'Call robot and the child walks stiff and squeezes every muscle; call rag doll and they flop, arms swinging, face soft. Alternate a few times, then slow it down and ask what each one feels like in the shoulders, hands and jaw. Children learn relaxation faster from contrast than from being told to relax. Coach the parent to play it daily for a week at a calm time and then to say rag doll softly as a cue when the child is winding up. Keep it silly; the laughing is part of what loosens the body. Children with motor or sensory differences can do a hand-only version.', '[{"id": "f0", "type": "textarea", "label": "What my body feels like as a robot:"}, {"id": "f1", "type": "textarea", "label": "What my body feels like as a rag doll:"}, {"id": "f2", "type": "textarea", "label": "The part of me that gets most robot when I am upset:"}, {"id": "f3", "type": "textarea", "label": "A time this week I turned into a rag doll on purpose:"}, {"id": "f4", "type": "textarea", "label": "Parent: when we played, and whether the rag doll cue helped in a real moment:"}]'::jsonb, array['children', 'regulation', 'play']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('rice-bin-hidden-treasures-calm-dig-play', 'Rice Bin Hidden Treasures Calm Dig Play', 'kids'::resource_kind, 'A sensory bin of dry rice with small objects hidden in it for a child to find slowly by touch with eyes closed.', 'Use it to give a child a hands-in calming activity and a parent a way to sit alongside without directing.', array['Children']::text[], '15 minutes', 'Fill a shallow bin with dry rice and bury five or six small objects: a button, a shell, a toy car. The child digs slowly with eyes closed, names what they feel before pulling it out, and sets each find on a cloth. The slowness is the skill, so coach the parent to resist hurrying or quizzing and simply to dig in their own corner of the bin. Ask the child afterward how their body felt before and after. Families can keep the bin for hard afternoons and swap the treasures weekly. Mind choking hazards for younger siblings, and check for rice allergies in the home.', '[{"id": "f0", "type": "textarea", "label": "The treasures I found, in the order I found them:"}, {"id": "f1", "type": "textarea", "label": "What my hands could tell about each one before I pulled it out:"}, {"id": "f2", "type": "textarea", "label": "How my body felt before the bin and after:"}, {"id": "f3", "type": "textarea", "label": "What I want to hide in the bin next time:"}, {"id": "f4", "type": "textarea", "label": "Parent: when we used the bin this week and what I noticed in my child:"}]'::jsonb, array['children', 'grounding', 'play']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('butterfly-net-thought-catcher-craft', 'Butterfly Net Thought Catcher Craft', 'kids'::resource_kind, 'A child makes a small net from a hanger and mesh and catches worried thoughts on paper butterflies to look at and let go.', 'Use it to help a child notice a worried thought as a thing they caught rather than a thing they are.', array['Children']::text[], '30 minutes to make, then a few minutes a day', 'Bend a wire hanger into a loop and stretch an old mesh bag or tulle over it. Cut out paper butterflies, and when a worried thought shows up the child writes or draws it on a butterfly and drops it in the net. Once a day, with a parent, they take the butterflies out, look at each one, say whether it is still fluttering, and either let it go out the window or keep it to talk about. The parent’s job is to be curious about the butterflies, not to fix them. Children who cannot write yet can dictate. Keep it playful; the net is for noticing, not for making worries disappear.', '[{"id": "f0", "type": "textarea", "label": "The butterflies I caught this week, in a few words each:"}, {"id": "f1", "type": "textarea", "label": "Which ones were still fluttering when we looked, and which had gone quiet:"}, {"id": "f2", "type": "textarea", "label": "The butterflies I let go, and the ones I wanted to keep to talk about:"}, {"id": "f3", "type": "textarea", "label": "What it is like to catch a worry instead of carrying it around:"}, {"id": "f4", "type": "textarea", "label": "Parent: what our daily butterfly look was like and what my child wanted to talk about:"}]'::jsonb, array['children', 'worry', 'craft']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('yes-and-story-circle-improv-game', 'Yes And Story Circle Improv Game', 'game'::resource_kind, 'A circle improv game where each player accepts what the last one said and adds to it, building a story without blocking.', 'Use it to practice accepting other people’s ideas and adding to them instead of correcting or shutting down.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Rules: one player starts a story with a single sentence. The next must begin with yes, and, accept everything said so far, and add one sentence. Blocking (no, actually, that didn’t happen) costs a point and the story restarts. Play three rounds, then a round where a player is secretly assigned to block and the group notices how it feels. Debrief on where blocking shows up in real conversations at home or school, and on what it was like to be built on rather than corrected. Keep stories short and silly; the point is the move, not the plot.', '[{"id": "f0", "type": "textarea", "label": "A moment in the game when someone built on my idea, and how that felt:"}, {"id": "f1", "type": "textarea", "label": "A moment I wanted to block, and what I said instead:"}, {"id": "f2", "type": "textarea", "label": "What the group noticed when the secret blocker was playing:"}, {"id": "f3", "type": "textarea", "label": "Where blocking shows up in my real conversations:"}, {"id": "f4", "type": "textarea", "label": "One conversation this week where I will try yes, and:"}]'::jsonb, array['game', 'group', 'communication']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('count-to-twenty-group-listening-game', 'Count to Twenty Group Listening Game', 'game'::resource_kind, 'A group tries to count aloud to twenty with no order and no signals, restarting whenever two people speak at once.', 'Use it to practice tuning in to a group, tolerating silence and waiting for the right moment to speak.', array['Groups', 'Teens', 'Adults']::text[], '15 minutes', 'Rules: the group sits in a circle, eyes closed or down. Anyone may say the next number, but nobody may speak twice in a row and no one may signal. If two people speak at once, the count returns to one. Most groups take several tries, and the silences get longer and more comfortable as they go. Debrief on what it was like to wait, who jumped in and who held back, and how the group figured out a rhythm without talking about it. This is a good opener for groups working on interrupting, social anxiety or trust, and takes almost no setup.', '[{"id": "f0", "type": "textarea", "label": "How many tries it took us, and what changed between the first and the last:"}, {"id": "f1", "type": "textarea", "label": "Whether I tended to jump in or hold back, and how that felt:"}, {"id": "f2", "type": "textarea", "label": "What the silences were like by the end:"}, {"id": "f3", "type": "textarea", "label": "How the group found a rhythm without anyone leading:"}, {"id": "f4", "type": "textarea", "label": "Where in my life I rush to speak or wait too long, and what the game suggests:"}]'::jsonb, array['game', 'group', 'mindfulness']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('zip-zap-zop-attention-circle-game', 'Zip Zap Zop Attention Circle Game', 'game'::resource_kind, 'A fast circle game of passing energy with three words and a clap, where a dropped beat sends the game back to the start.', 'Use it to warm up a group’s attention and give an easy, forgiving way to practice making mistakes in public.', array['Groups', 'Teens', 'Children']::text[], '10 minutes', 'Rules: players stand in a circle. One claps toward another and says zip; that player claps toward someone else and says zap; the next says zop, and the cycle repeats. The receiver must be clear from eye contact and the clap. A wrong word or a hesitation longer than a beat means the group cheers, and that player restarts with zip. The cheer on a mistake is the point: the game trains the group to treat a slip as part of the fun. Speed it up round by round. Debrief on what it was like to mess up and be cheered, and where else that would help.', '[{"id": "f0", "type": "textarea", "label": "What happened in my body when the zip came to me:"}, {"id": "f1", "type": "textarea", "label": "A time I messed up and the group cheered, and what that was like:"}, {"id": "f2", "type": "textarea", "label": "How fast we got by the last round:"}, {"id": "f3", "type": "textarea", "label": "Where else in my week a mistake could be met with a cheer instead of a wince:"}, {"id": "f4", "type": "textarea", "label": "One thing I noticed about staying alert without being tense:"}]'::jsonb, array['game', 'group', 'play']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('lava-floor-cooperative-crossing-game', 'Lava Floor Cooperative Crossing Game', 'game'::resource_kind, 'A team crosses the room on a limited number of paper stepping stones that disappear if nobody is touching them.', 'Use it to practice planning together, asking for help and staying calm when the plan goes wrong.', array['Groups', 'Children', 'Teens']::text[], '25 minutes', 'Rules: the floor is lava. The team gets fewer paper stones than people and must get everyone across. A stone that nobody is touching at any moment is removed by the leader. Anyone who touches the floor returns to the start, and the team decides together whether to restart the whole crossing. Let a plan fail at least once before stepping in. Debrief on how decisions were made, who got heard, what happened when a stone was lost, and how the team spoke to the person who fell in. Children love it; teens and adults find the debrief surprisingly pointed.', '[{"id": "f0", "type": "textarea", "label": "Our plan before we started, and what actually happened:"}, {"id": "f1", "type": "textarea", "label": "What the team said to the person who touched the lava:"}, {"id": "f2", "type": "textarea", "label": "A moment I asked for help or offered it:"}, {"id": "f3", "type": "textarea", "label": "How we decided things, and whether everyone got heard:"}, {"id": "f4", "type": "textarea", "label": "What this crossing had in common with a real group I am part of:"}]'::jsonb, array['game', 'group', 'teamwork']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('heading-west-values-are-a-direction-page', 'Heading West Values Are a Direction Page', 'act'::resource_kind, 'A page using the image of heading west to separate values, which are a direction, from goals, which are places you arrive.', 'Use it to help a client who feels they keep failing see that a value is never finished and can be lived today.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients often treat values like goals and then feel they have failed them: I value health, and I missed the gym. Draw a compass. Heading west is a direction you can take at any moment and never complete; the town you reach on the way is a goal. Have the client name three values as directions, then for each one list the towns, the goals, they have been confusing with the direction. Then ask what one step west would look like today, even on a day when every goal is out of reach. This often lifts the all-or-nothing from a client’s week and makes a bad day a day of heading west anyway.', '[{"id": "f0", "type": "textarea", "label": "Three values I hold, written as directions rather than destinations:"}, {"id": "f1", "type": "textarea", "label": "For each one, the goals I have been confusing with the direction:"}, {"id": "f2", "type": "textarea", "label": "A recent day I felt I failed a value, and whether I was actually failing a goal:"}, {"id": "f3", "type": "textarea", "label": "One step west for each value that I could take today, however small:"}, {"id": "f4", "type": "textarea", "label": "What changes when a value is a direction I can take at any moment:"}]'::jsonb, array['core ACT', 'values', 'committed action']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('sculptor-and-clay-pairs-game', 'Sculptor and Clay Pairs Game', 'game'::resource_kind, 'A pairs game where one player gently poses the other like clay into a feeling or a scene, and the group guesses it.', 'Use it to practice asking for and giving consent to touch, reading a body’s posture, and being handled gently.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Rules: in pairs, one is the sculptor and one is the clay. The sculptor asks permission before each adjustment, moves the clay slowly into a pose that shows a feeling or a scene, and the clay may say no to any move, which is honored without discussion. The group guesses the feeling. Swap roles. Debrief on what it was like to be moved gently and to say no, what the sculptor noticed about asking, and how posture alone carried the feeling. Offer a no-touch version where the sculptor demonstrates and the clay copies, and make it clear anyone may choose that version without explaining.', '[{"id": "f0", "type": "textarea", "label": "The feeling or scene I sculpted, and whether the group guessed it:"}, {"id": "f1", "type": "textarea", "label": "What it was like to be the clay and to be moved gently:"}, {"id": "f2", "type": "textarea", "label": "A moment I said no, or wanted to, and what happened:"}, {"id": "f3", "type": "textarea", "label": "What I noticed about asking permission before each move:"}, {"id": "f4", "type": "textarea", "label": "What posture alone told the group, without a face or a word:"}]'::jsonb, array['game', 'group', 'boundaries']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('loud-noise-plan-ear-muff-decorating-craft', 'Loud Noise Plan Ear Muff Decorating Craft', 'kids'::resource_kind, 'A child decorates a pair of ear defenders and makes a plan with a parent for loud places and sudden bangs.', 'Use it to give a child who startles at noise a tool they chose and a parent a shared plan for the moment.', array['Children']::text[], '30 minutes', 'Bring a plain pair of child ear defenders or soft earmuffs and stickers, fabric markers and ribbon. While the child decorates, talk about the loud things that are hard, and write the plan on the sheet: where the muffs live, who carries them, the signal the child gives, and what the parent does. Keep the talk on the here and now; this is a tool for a stabilizing plan, not a conversation about what happened. Coach the parent to practice the signal at home in a calm moment. If a child discloses abuse or harm during the activity, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The colors and stickers I chose for my ear muffs:"}, {"id": "f1", "type": "textarea", "label": "The loud things that are hardest for me right now:"}, {"id": "f2", "type": "textarea", "label": "My signal that tells my grown-up I need my muffs or a quieter spot:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up will do when they see the signal:"}, {"id": "f4", "type": "textarea", "label": "Parent: where the muffs live, who carries them, and how our practice went:"}]'::jsonb, array['PTSD and trauma', 'children', 'safety']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('driving-again-after-the-accident-steps-sheet', 'Driving Again After the Accident Steps Sheet', 'worksheet'::resource_kind, 'A paced plan for returning to the driver’s seat after a crash, from sitting in the parked car to a short familiar route.', 'Use it to help a client rebuild driving in small, chosen steps with support and grounding at each one.', array['Adults', 'Teens']::text[], 'Several weeks', 'Build the ladder with the client: sitting in the parked car with the engine off, engine on in the driveway, around the block with a passenger, a familiar route at a quiet hour, and so on. Each step has a grounding plan and a support person named, and the client decides when a step is done. Keep the work on the present and on safety; this is not the place to recount the crash, and no step should be set as homework that the client has not agreed to in session. Expect body reactions at intersections, and plan routes that avoid the crash site until later. Progress is the client’s to pace.', '[{"id": "f0", "type": "textarea", "label": "Where I am now with driving, honestly:"}, {"id": "f1", "type": "textarea", "label": "The steps between here and the driving I want back, from easiest to hardest:"}, {"id": "f2", "type": "textarea", "label": "What I will do to ground myself before and during each step:"}, {"id": "f3", "type": "textarea", "label": "Who will be with me or on call, and what I want them to say or not say:"}, {"id": "f4", "type": "textarea", "label": "How I will know a step is done and I am ready for the next:"}, {"id": "f5", "type": "textarea", "label": "Routes or places I will leave for later, and that is okay:"}]'::jsonb, array['PTSD and trauma', 'pacing', 'safety']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('permission-to-enjoy-things-again-page', 'Permission to Enjoy Things Again Page', 'act'::resource_kind, 'A values page for the client who feels guilty or unsafe when a good moment arrives after a hard time.', 'Use it to help a client notice the pull to shut down enjoyment and choose to let a small good moment stay.', array['Adults', 'Teens']::text[], '20 minutes', 'After a frightening or painful period, some clients treat enjoyment as disloyal or as letting their guard down. Ask what the mind says when a good moment arrives, and what the client does with the moment: cut it short, undercut it, stay braced. Then connect enjoyment to their values: what does laughing with a friend serve? Set a small willingness exercise, one good moment this week they will let run for sixty seconds longer than usual, noticing what the mind says and staying anyway. Keep the frame present-focused and gentle, and do not require the client to explain where the guilt came from.', '[{"id": "f0", "type": "textarea", "label": "What my mind says when something starts to feel good:"}, {"id": "f1", "type": "textarea", "label": "What I usually do with a good moment: cut it short, undercut it, stay braced, or something else:"}, {"id": "f2", "type": "textarea", "label": "The values a good moment serves, when I let it:"}, {"id": "f3", "type": "textarea", "label": "One good moment this week I am willing to let run sixty seconds longer:"}, {"id": "f4", "type": "textarea", "label": "What I noticed when I stayed:"}]'::jsonb, array['PTSD and trauma', 'willingness', 'values']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('irritability-after-a-bad-night-thought-check-sheet', 'Irritability After a Bad Night Thought Check Sheet', 'cbt'::resource_kind, 'A thought check for the harsh self-talk that follows snapping at someone after a night of poor sleep.', 'Use it to help a client separate a sleep-starved short fuse from the belief that they are a bad person.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients with disturbed sleep often arrive ashamed of how they spoke to a partner or child the morning after. Walk through the moment: hours slept, what was said, and the thought that followed, which is usually about character rather than tiredness. Then look at the evidence a tired body offers, what the client would say to a friend who had the same night, and a repair they can make. If the nights are driven by nightmares or hypervigilance, keep this sheet on the morning and address the nights separately.', '[{"id": "f0", "type": "textarea", "label": "How I slept, roughly, and what the morning was like:"}, {"id": "f1", "type": "textarea", "label": "What I said or did that I regret, as plainly as I can put it:"}, {"id": "f2", "type": "textarea", "label": "The thought I had about myself afterward:"}, {"id": "f3", "type": "textarea", "label": "How much of the morning the night explains, and how much it does not:"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend who had the same night and the same morning:"}, {"id": "f5", "type": "textarea", "label": "The repair I will make, and my plan for the next morning after a bad night:"}]'::jsonb, array['PTSD and trauma', 'sleep', 'thinking traps']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('questions-i-am-afraid-to-ask-sheet-for-partners', 'Questions I Am Afraid to Ask Sheet for Partners', 'couples'::resource_kind, 'A sheet where the partner of someone carrying trauma writes the questions they have been holding, and both agree which to answer and when.', 'Use it to let a couple handle a partner’s unasked questions with pacing and consent instead of silence or ambush.', array['Couples']::text[], '45 minutes in session', 'The supporting partner lists, privately, the questions they have wanted to ask and have not: about triggers, about what helps, about the future. The client carrying the trauma reads the list and sorts each question into answer now, answer later, and not something I will answer. Answers stay at the level of what helps and what to expect, never the details of what happened, and the clinician holds that line. Many partners mostly want to know how to help and whether they are making it worse, and hearing that answered relieves both. Revisit the later pile when the client chooses.', '[{"id": "f0", "type": "textarea", "label": "Supporting partner: the questions I have been holding, as plainly as I can write them:"}, {"id": "f1", "type": "textarea", "label": "Partner carrying this: which questions I can answer now, which later, and which I will not:"}, {"id": "f2", "type": "textarea", "label": "Partner carrying this: the answers I am willing to give now, kept to what helps and what to expect:"}, {"id": "f3", "type": "textarea", "label": "Supporting partner: what I heard, and what I will do differently:"}, {"id": "f4", "type": "textarea", "label": "Both: how we will handle a new question when it comes up at home:"}]'::jsonb, array['PTSD and trauma', 'couples', 'pacing']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('postpone-the-peek-envelope-game', 'Postpone the Peek Envelope Game', 'game'::resource_kind, 'A group game where each player holds a sealed envelope that may or may not hold a prize, and the first to open theirs loses it.', 'Use it to let a group practice sitting with not knowing and notice how the urge to find out rises and falls.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Rules: each player gets a sealed envelope; some hold a small prize, some a blank card, and nobody knows which. The group talks, plays a side game or does an ordinary task for twenty minutes while holding the envelope. Anyone who opens theirs early forfeits whatever is inside. Every five minutes, players rate their urge to peek on their fingers. At the end, everyone opens together. Debrief on how the urge moved over time, what people did with it, and what the envelope stands for in their lives. Keep prizes small and silly so the game stays about the waiting.', '[{"id": "f0", "type": "textarea", "label": "My urge to open the envelope at each five-minute check, 0 to 10:"}, {"id": "f1", "type": "textarea", "label": "What I did with the urge while we waited:"}, {"id": "f2", "type": "textarea", "label": "What my mind said was in the envelope, and what was actually there:"}, {"id": "f3", "type": "textarea", "label": "Something in my life that feels like a sealed envelope right now:"}, {"id": "f4", "type": "textarea", "label": "What I learned about waiting from how the urge moved:"}]'::jsonb, array['anxiety', 'game', 'uncertainty']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('describe-the-worry-just-the-facts-card', 'Describe the Worry Just the Facts Card', 'dbt'::resource_kind, 'A describe-skill card for stating a worry in observable facts only, stripped of predictions and judgments.', 'Use it to help a client shrink a swelling worry to the facts it actually contains.', array['Adults', 'Teens']::text[], 'Five minutes per worry', 'The mindfulness describe skill: words for what is observed, nothing more. Have the client write the worry as it first arrives, then rewrite it keeping only what a camera or a calendar could confirm: the email has not been answered in two days. Predictions, mind-reading and judgments go in a separate box labeled added by my mind. The facts version is usually short and often oddly manageable. Practice on three worries in session so the client can feel the difference, then hand them the card. Pair with check the facts when the client wants to go further; this card stops at the sorting.', '[{"id": "f0", "type": "textarea", "label": "The worry as it arrived, in my mind’s own words:"}, {"id": "f1", "type": "textarea", "label": "Just the facts: what a camera or a calendar could confirm:"}, {"id": "f2", "type": "textarea", "label": "Added by my mind: the predictions, mind-reading and judgments I stripped out:"}, {"id": "f3", "type": "textarea", "label": "How the facts version feels compared with the original:"}, {"id": "f4", "type": "textarea", "label": "What, if anything, the facts version asks me to do:"}]'::jsonb, array['anxiety', 'core DBT', 'mindfulness']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('vague-dread-to-specific-worry-sheet', 'Vague Dread to Specific Worry Sheet', 'cbt'::resource_kind, 'A sheet for turning a formless sense of dread into named, specific worries that can each be looked at.', 'Use it to help a client who feels anxious about nothing in particular find the particular things underneath.', array['Adults', 'Teens']::text[], '20 minutes', 'Free-floating dread resists every thought record because there is no thought to record. Start with the body and the time of day the dread is strongest, then ask the client to finish the sentence if I had to guess, it is about, five times, without censoring. Most produce three or four specific worries, some of which are solvable and some of which are old friends. Sort them: has a next step, needs a thought check, or is a worry about worrying. The dread usually shrinks once it has names, and the client leaves with a plan for one of them rather than a fog. Repeat when the fog returns.', '[{"id": "f0", "type": "textarea", "label": "Where the dread sits in my body and when it is strongest:"}, {"id": "f1", "type": "textarea", "label": "If I had to guess, it is about: (five guesses, no censoring)"}, {"id": "f2", "type": "textarea", "label": "Which guesses have a next step I could take:"}, {"id": "f3", "type": "textarea", "label": "Which guesses are thoughts to check rather than problems to solve:"}, {"id": "f4", "type": "textarea", "label": "Which guesses are really a worry about feeling worried:"}, {"id": "f5", "type": "textarea", "label": "The one I will work on first, and how:"}]'::jsonb, array['anxiety', 'core CBT', 'worry']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('plans-changing-last-minute-talk-sheet-for-partners', 'Plans Changing Last Minute Talk Sheet for Partners', 'couples'::resource_kind, 'A talk sheet for couples where one partner needs plans fixed and the other changes them freely, and both end up hurt.', 'Use it to help partners understand what a changed plan costs the anxious partner and what rigidity costs the other.', array['Couples']::text[], '40 minutes', 'One partner relaxes when the evening is settled; the other relaxes when it is open. Each describes, without blame, what happens inside them when a plan changes at the last minute or when it cannot change at all. Then they design two things: a heads-up habit for the flexible partner, and a small tolerance practice for the anxious partner, such as leaving one evening a week deliberately unplanned. Watch for the flexible partner treating the anxiety as the whole problem, and for the anxious partner using it as a veto. The agreement should cost each of them a little.', '[{"id": "f0", "type": "textarea", "label": "Partner who likes plans fixed: what happens in me when a plan changes at the last minute:"}, {"id": "f1", "type": "textarea", "label": "Partner who likes plans open: what happens in me when nothing can move:"}, {"id": "f2", "type": "textarea", "label": "Our heads-up habit: how and how early a change will be mentioned:"}, {"id": "f3", "type": "textarea", "label": "Our tolerance practice: the small unplanned space we will leave each week:"}, {"id": "f4", "type": "textarea", "label": "What each of us will say when the agreement slips:"}]'::jsonb, array['anxiety', 'couples', 'uncertainty']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('i-used-to-be-able-to-thought-check-sheet', 'I Used to Be Able To Thought Check Sheet', 'cbt'::resource_kind, 'A thought check for the comparison between the client now and a remembered past self who could do everything.', 'Use it to test a client’s rosy memory of their past capacity against the facts and set a fair standard for now.', array['Adults', 'Teens']::text[], '20 minutes', 'Low mood edits memory: the past self ran every morning and never struggled. Write down the comparison the client makes, then check it: was that self ever real for more than a season, what was different about their life then, and what would they have said about themselves at the time? Then ask what a fair expectation of a person in the client’s current circumstances would be, as if describing a friend. The goal is a standard the client can meet and build from, not a verdict that they have declined. Watch for grief about real losses of capacity and name it rather than arguing with it.', '[{"id": "f0", "type": "textarea", "label": "The comparison I keep making: I used to be able to, and now I:"}, {"id": "f1", "type": "textarea", "label": "Whether that past self was ever real for more than a season, honestly:"}, {"id": "f2", "type": "textarea", "label": "What was different about my life, support and energy then:"}, {"id": "f3", "type": "textarea", "label": "What that past self would have said about themselves at the time:"}, {"id": "f4", "type": "textarea", "label": "A fair expectation of someone in my current circumstances:"}, {"id": "f5", "type": "textarea", "label": "One thing I can do this week at that fair standard:"}]'::jsonb, array['depression', 'core CBT', 'thinking traps']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('low-mood-as-weather-not-climate-page', 'Low Mood as Weather Not Climate Page', 'act'::resource_kind, 'A page that separates today’s mood, which changes like weather, from the client’s mind’s claim that this is the permanent climate.', 'Use it to loosen the thought that a low day is forever and reconnect the client with what they would do in any weather.', array['Adults', 'Teens']::text[], '20 minutes', 'When mood is low the mind forecasts that it always will be, and the client plans their life around the forecast. Have them list the mind’s climate statements and then, from memory or a mood log, the actual weather of the last two weeks: the hours or days that were different. Then ask what they do in any weather, the way a person still feeds the dog in the rain, and name those as values-based actions to keep regardless of the day’s reading. This is not an argument that the mood will lift on schedule, only that forecasts are thoughts. Pair with behavioral activation if the client is ready.', '[{"id": "f0", "type": "textarea", "label": "What my mind says the climate is:"}, {"id": "f1", "type": "textarea", "label": "The actual weather of the last two weeks: hours or days that were different, however small:"}, {"id": "f2", "type": "textarea", "label": "The things I do in any weather, rain or shine:"}, {"id": "f3", "type": "textarea", "label": "One values-based action I will keep this week regardless of the day’s reading:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the forecast once I looked at the weather record:"}]'::jsonb, array['depression', 'defusion', 'values']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('burden-on-others-check-the-facts-sheet', 'Burden on Others Check the Facts Sheet', 'dbt'::resource_kind, 'A check-the-facts sheet for the belief that the client is a weight on the people around them.', 'Use it to test a burden belief against what the people in question have actually said and done.', array['Adults', 'Teens']::text[], '20 minutes in session', 'The thought that one is a burden is common in low mood and feeds withdrawal. Run check the facts: what is the emotion, what exactly is the client assuming about each person, what have those people actually said and done, and what are other interpretations of the same facts? Then ask whether the intensity fits. Complete this in session rather than as homework, because the thought can sit near hopelessness; if the client hints at not wanting to be here, address that directly and name 988 as a resource they can call or text. Finish with one act of reaching out that the facts support.', '[{"id": "f0", "type": "textarea", "label": "The thought, and the emotion that goes with it:"}, {"id": "f1", "type": "textarea", "label": "The people I believe I am a burden to, and what exactly I assume each one thinks:"}, {"id": "f2", "type": "textarea", "label": "What each of them has actually said and done, including recently:"}, {"id": "f3", "type": "textarea", "label": "Other ways to read the same facts:"}, {"id": "f4", "type": "textarea", "label": "Whether the size of the feeling fits the facts, and what would fit:"}, {"id": "f5", "type": "textarea", "label": "If this thought ever turns into not wanting to be here, I can call or text 988, and I will tell:"}, {"id": "f6", "type": "textarea", "label": "One reach-out the facts support this week:"}]'::jsonb, array['depression', 'core DBT', 'emotion regulation']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('covering-tasks-without-keeping-a-tab-sheet', 'Covering Tasks Without Keeping a Tab Sheet', 'couples'::resource_kind, 'An agreement sheet for couples where one partner is in a low stretch and the other is carrying more of the household.', 'Use it to help a couple share the load during a hard season without resentment on one side or guilt on the other.', array['Couples']::text[], '30 minutes', 'When one partner is in a low period, the other often quietly takes over and keeps an unspoken tab, while the low partner sees the tab and feels worse. Name this openly. The partner carrying more lists what they are covering and what they genuinely need back, which is often acknowledgment rather than tasks. The low partner names two or three things they can still reliably do, however small, and both agree how the arrangement will be reviewed and when. Keep the tone practical. A season with a plan and a review date feels different from an indefinite imbalance.', '[{"id": "f0", "type": "textarea", "label": "Partner carrying more: what I am covering right now, as a plain list:"}, {"id": "f1", "type": "textarea", "label": "Partner carrying more: what I actually need back, in words or in tasks:"}, {"id": "f2", "type": "textarea", "label": "Partner in the low stretch: two or three things I can still reliably do this week:"}, {"id": "f3", "type": "textarea", "label": "Partner in the low stretch: what I need to hear instead of a tab being kept:"}, {"id": "f4", "type": "textarea", "label": "Both: when we will review this arrangement, and what would tell us to change it:"}]'::jsonb, array['depression', 'couples', 'support']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('buffer-minutes-before-leaving-planner-sheet', 'Buffer Minutes Before Leaving Planner Sheet', 'worksheet'::resource_kind, 'A planner that counts the real minutes between deciding to leave and actually being out the door, then builds them in.', 'Use it to end chronic lateness by planning for the leaving process instead of the departure time.', array['Adults', 'Teens']::text[], '20 minutes, then one week of use', 'Clients with attention difficulties often set the leaving time as the moment they must be in the car, forgetting the shoes, keys, bathroom, forgotten item and one last thing. Time the actual leaving process twice, from the decision to the door closing. Then set the alarm for that many minutes before the needed departure, plus five. Ask the client to list their personal last-minute items so they can be staged the night before. Review after a week: which buffers held, and what new item appeared. Keep the tone practical; lateness is usually a measurement problem, not a character one.', '[{"id": "f0", "type": "textarea", "label": "How many minutes it actually took me to leave, timed twice:"}, {"id": "f1", "type": "textarea", "label": "My last-minute items that always appear: the ones I can stage the night before:"}, {"id": "f2", "type": "textarea", "label": "The buffer I will set before each departure this week, including the extra five:"}, {"id": "f3", "type": "textarea", "label": "What happened each day: on time, late, and by how much:"}, {"id": "f4", "type": "textarea", "label": "The new last-minute item that showed up, and where it will live:"}]'::jsonb, array['ADHD', 'planning', 'routines']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('i-will-remember-without-writing-it-belief-test', 'I Will Remember Without Writing It Belief Test', 'cbt'::resource_kind, 'A one-week experiment testing the client’s belief that they will remember things without writing them down.', 'Use it to let the client find out, with their own data, how often an unwritten intention survives the day.', array['Adults', 'Teens']::text[], 'One week', 'Many clients refuse lists because they believe they will remember, and treat the forgetting as a one-off every time. Set up the test: each morning they tell someone, or record a voice note, of the three things they intend to remember that day without writing them anywhere. At night they check how many happened. For comparison, in the second half of the week they write three items on a card they carry. Compare the two halves. The client, not you, draws the conclusion. If the written list also fails, the problem is checking the list, which is a different experiment.', '[{"id": "f0", "type": "textarea", "label": "My prediction: out of three unwritten items a day, how many I will remember:"}, {"id": "f1", "type": "textarea", "label": "Days one to three: the three items, and which ones happened:"}, {"id": "f2", "type": "textarea", "label": "Days four to six: the three written items, and which ones happened:"}, {"id": "f3", "type": "textarea", "label": "What the two halves show when I put them side by side:"}, {"id": "f4", "type": "textarea", "label": "What I will do with the result, even if I do not like it:"}]'::jsonb, array['ADHD', 'behavioral experiment', 'core CBT']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('task-switch-urge-observe-card', 'Task Switch Urge Observe Card', 'dbt'::resource_kind, 'A mindfulness card for noticing the urge to switch tasks, describing it and staying for one more minute.', 'Use it to help a client observe the pull to switch rather than obey it, and build a minute of stay at a time.', array['Adults', 'Teens']::text[], 'A few minutes, many times a day', 'The observe skill applied to the moment attention wants to leave. The client notices the urge to check, switch tabs or get up, names it silently as urge, describes where it sits in the body, and sets a one-minute timer before deciding. Most urges either fade or turn into a specific need that can be scheduled. Have the client tally urges and stays for a few days without judging the ratio; staying three times out of ten is a start. Keep the card beside the work. This pairs with a body-doubling arrangement or a timer method, and is not a replacement for a work setup that fits the client.', '[{"id": "f0", "type": "textarea", "label": "What the urge to switch feels like in my body, and the word I will use for it:"}, {"id": "f1", "type": "textarea", "label": "My tally for today: urges noticed, and minutes I stayed:"}, {"id": "f2", "type": "textarea", "label": "What the urge turned into when I waited a minute: nothing, a real need, or something to schedule:"}, {"id": "f3", "type": "textarea", "label": "The task that drew the most urges, and what that tells me:"}, {"id": "f4", "type": "textarea", "label": "One change to my setup that would make staying easier:"}]'::jsonb, array['ADHD', 'core DBT', 'mindfulness']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('waiting-turn-sand-timer-craft', 'Waiting Turn Sand Timer Craft', 'kids'::resource_kind, 'A child builds a sand timer from two bottles and uses it to see how long a turn or a wait really is.', 'Use it to make waiting visible for a child who finds turns endless, with a parent running the timer at home.', array['Children']::text[], '30 minutes to make', 'Tape two small clear bottles neck to neck with a piece of card between them, punch a hole in the card, and fill one side with fine sand or salt. The child decorates the outside and times the sand with a stopwatch, then uses the timer for turns with siblings, screen breaks or waiting for a parent to finish a call. Seeing the sand move gives the wait a shape. Coach the parent to hand the child the timer when saying wait, and to keep their word when the sand runs out, which is what makes the timer trustworthy. Children can decorate a second timer for a longer wait.', '[{"id": "f0", "type": "textarea", "label": "How long my timer runs, by the stopwatch:"}, {"id": "f1", "type": "textarea", "label": "The waits I will use it for at home:"}, {"id": "f2", "type": "textarea", "label": "What I can do while the sand is running:"}, {"id": "f3", "type": "textarea", "label": "A time this week the timer made a wait easier:"}, {"id": "f4", "type": "textarea", "label": "Parent: how I used the timer, and whether I kept my word when the sand ran out:"}]'::jsonb, array['ADHD', 'children', 'craft']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('partner-not-parent-role-reset-sheet', 'Partner Not Parent Role Reset Sheet', 'couples'::resource_kind, 'A sheet for couples where one partner has slipped into managing the other’s attention and tasks like a parent.', 'Use it to name the manager and managed roles a couple has fallen into and rebuild an arrangement between equals.', array['Couples']::text[], '45 minutes', 'When one partner has attention difficulties, the other often becomes the reminder system, and both come to resent it: one feels nagged and small, the other exhausted and unseen. Each describes the role they have fallen into and what it costs them. Then they move reminders out of the relationship and into systems: shared calendars, alarms, a visible board, agreed check-in times. The managing partner practices letting a consequence land without rescuing; the other practices owning the system. Review in two weeks. The aim is two adults with a shared system, not a better manager.', '[{"id": "f0", "type": "textarea", "label": "Partner who manages: the role I have fallen into, and what it costs me:"}, {"id": "f1", "type": "textarea", "label": "Partner who is managed: the role I have fallen into, and what it costs me:"}, {"id": "f2", "type": "textarea", "label": "The reminders we will move out of the relationship and into a system, and which system:"}, {"id": "f3", "type": "textarea", "label": "What the managing partner will stop doing, even when it is uncomfortable:"}, {"id": "f4", "type": "textarea", "label": "What the other partner will own, and how we will both know it is working:"}, {"id": "f5", "type": "textarea", "label": "Our review date and what we will look at:"}]'::jsonb, array['ADHD', 'couples', 'boundaries']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('everyone-uses-like-me-assumption-check-sheet', 'Everyone Uses Like Me Assumption Check Sheet', 'cbt'::resource_kind, 'An assumption check for the belief that the client’s substance use is simply what everyone around them does.', 'Use it to help a client look at who they are comparing themselves with and what that comparison hides.', array['Adults', 'Teens']::text[], '20 minutes', 'The thought everyone drinks like this or everyone I know uses keeps substance use feeling ordinary. Ask the client to list the actual people behind the word everyone, then widen the circle: coworkers, family, old friends, neighbors. Then look at how the circle was chosen and whether the people in it were chosen because they use. The point is not to shame the client’s friends but to show that a reference group is a choice. Finish by asking who in the wider circle the client would like their life to look more like, and what one evening with them would involve.', '[{"id": "f0", "type": "textarea", "label": "The people I actually mean when I say everyone:"}, {"id": "f1", "type": "textarea", "label": "The wider circle: coworkers, family, old friends, neighbors, and how their use compares:"}, {"id": "f2", "type": "textarea", "label": "How my inner circle got chosen, honestly:"}, {"id": "f3", "type": "textarea", "label": "What the comparison with everyone lets me not look at:"}, {"id": "f4", "type": "textarea", "label": "Someone in the wider circle whose life I would like mine to look more like, and one evening with them:"}]'::jsonb, array['addiction', 'core CBT', 'thinking traps']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('sober-firsts-willingness-page', 'Sober Firsts Willingness Page', 'act'::resource_kind, 'A willingness page for the first wedding, first holiday, first bad day or first celebration without the substance.', 'Use it to help a client approach a first without the substance as a chosen, values-based step rather than a test.', array['Adults', 'Teens']::text[], '20 minutes before each first', 'Early in a change in substance use, the firsts loom: the first party, the first funeral, the first Friday. Have the client name the next one, write what the mind forecasts, and rate willingness to attend with the forecast coming along for the ride. Then connect the event to a value: being present for a friend. Plan the practical pieces, including an exit, a support text and what to hold in the hand. Afterward, record what the mind forecast versus what happened, and add the event to a growing list of firsts done. Urges during the event are expected and are not a failure.', '[{"id": "f0", "type": "textarea", "label": "The next first without the substance, and when it is:"}, {"id": "f1", "type": "textarea", "label": "What my mind forecasts about it:"}, {"id": "f2", "type": "textarea", "label": "The value that makes showing up matter to me:"}, {"id": "f3", "type": "textarea", "label": "My plan: exit, support text, what I will hold in my hand, how I will handle an urge:"}, {"id": "f4", "type": "textarea", "label": "My willingness to go with the forecast riding along, 0 to 10:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what actually happened, and the first I can now add to my list:"}]'::jsonb, array['addiction', 'willingness', 'values']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('urge-hour-self-soothe-setup-card', 'Urge Hour Self-Soothe Setup Card', 'dbt'::resource_kind, 'A five-senses self-soothe plan built specifically for the hours and places where the substance used to do the soothing.', 'Use it to give a client a sensory plan for the exact moments the substance used to fill.', array['Adults', 'Teens']::text[], '20 minutes to build, then daily', 'Generic self-soothe lists often fail because they are not matched to the moment. Start with the client’s substance-use map: the hour, the room, the feeling. For each hot moment, build one soothing option per sense that can be in place at that hour and in that room: a specific scent by the couch, a playlist for the drive home, a hot drink in a particular mug. The plan goes where the urges live, not in a notebook. Review which options were used and which were never in reach. Keep language on substance use and urges, never on what kind of person the client is.', '[{"id": "f0", "type": "textarea", "label": "My hot moments for urges: hour, room, feeling:"}, {"id": "f1", "type": "textarea", "label": "For each hot moment, something to see, hear, smell, touch and taste that can be in place there:"}, {"id": "f2", "type": "textarea", "label": "What I need to buy or set up this week to have those in reach:"}, {"id": "f3", "type": "textarea", "label": "Which options I actually used, and which were never in reach:"}, {"id": "f4", "type": "textarea", "label": "The moment that still has nothing in it, and what I will try there:"}]'::jsonb, array['addiction', 'core DBT', 'urges']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('trigger-or-not-speed-sort-game', 'Trigger or Not Speed Sort Game', 'game'::resource_kind, 'A fast card-sorting game where players sort everyday situations into trigger, not a trigger and depends, then defend the sort.', 'Use it to help a group map their own triggers for urges quickly and see how differently the same situation lands.', array['Groups', 'Adults', 'Teens']::text[], '30 minutes', 'Rules: deal each player a set of situation cards (payday, a wedding, a fight with a parent, a sunny Friday, boredom at 9 pm). On go, each sorts their cards into three piles in sixty seconds. Then go around: each player names one card from their trigger pile and one from their not pile, and the group notices where the same card landed differently. The depends pile gets the most discussion. Debrief with each player writing their top three triggers and one plan for each. Keep it brisk and curious, and do not let the group rank anyone’s triggers as more or less serious.', '[{"id": "f0", "type": "textarea", "label": "My trigger pile, after sixty seconds:"}, {"id": "f1", "type": "textarea", "label": "My not a trigger pile, and one card there that surprised someone else:"}, {"id": "f2", "type": "textarea", "label": "My depends pile, and what it depends on:"}, {"id": "f3", "type": "textarea", "label": "A card that landed differently for me than for others, and what that showed:"}, {"id": "f4", "type": "textarea", "label": "My top three triggers for urges and one plan for each:"}]'::jsonb, array['addiction', 'game', 'urges']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('checking-up-versus-checking-in-sheet-for-partners', 'Checking Up Versus Checking In Sheet for Partners', 'couples'::resource_kind, 'A sheet that separates a partner’s surveillance of substance use from the connection both partners actually want.', 'Use it to help a couple replace checking up, which breeds hiding, with checking in, which rebuilds trust.', array['Couples']::text[], '40 minutes', 'After a period of substance use, the supporting partner often checks: receipts, breath, phone, hours. It is understandable and it corrodes. Each partner describes what checking up looks like and does to them. Then define checking in together: a question asked at an agreed time, answered honestly, with no search afterward. Agree what the partner with urges will volunteer and when, and what happens if a check-in reveals a slip, so honesty is not punished. Review in two weeks. Keep the language on substance use and urges, and keep both partners’ fear in the room without letting either one run it.', '[{"id": "f0", "type": "textarea", "label": "Supporting partner: what checking up looks like for me, and what it costs me:"}, {"id": "f1", "type": "textarea", "label": "Partner with urges: what being checked up on does to me, and what I then hide:"}, {"id": "f2", "type": "textarea", "label": "Our checking-in agreement: when, what question, and what will be volunteered without being asked:"}, {"id": "f3", "type": "textarea", "label": "What happens if a check-in reveals a slip, so that honesty is not punished:"}, {"id": "f4", "type": "textarea", "label": "What each of us will do with our fear instead of checking up:"}, {"id": "f5", "type": "textarea", "label": "Our review date:"}]'::jsonb, array['addiction', 'couples', 'support']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('bubble-wrap-stomp-path-cool-down-play', 'Bubble Wrap Stomp Path Cool Down Play', 'kids'::resource_kind, 'A child and parent tape a path of bubble wrap to the floor for stomping out anger, with a calm corner at the end.', 'Use it to give a child a safe, loud outlet for angry energy that ends somewhere quiet.', array['Children']::text[], '20 minutes to set up, then as needed', 'Tape a strip of large-bubble wrap along a hallway with a cushion, a book or a stuffed animal at the end. When anger rises, the child stomps the path, feeling and hearing the pops, and sits down at the end to do their breathing or hold the stuffed animal. The parent walks beside, not ahead, and does not talk about the problem until the child is seated and calmer. Set this up in a calm moment and practice it once for fun so the child knows the path. Replace the wrap when the pops are gone. Children who dislike loud pops can use a path of cushions to jump instead.', '[{"id": "f0", "type": "textarea", "label": "Where our stomp path is and what waits at the end:"}, {"id": "f1", "type": "textarea", "label": "What my feet and ears notice when I stomp:"}, {"id": "f2", "type": "textarea", "label": "What I do at the end of the path to get calmer:"}, {"id": "f3", "type": "textarea", "label": "A time this week I used the path, and what we talked about after:"}, {"id": "f4", "type": "textarea", "label": "Parent: how I walked beside and waited, and what I noticed in my child at the end:"}]'::jsonb, array['anger management', 'children', 'regulation']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('worth-it-annoyance-auction-game', 'Worth It Annoyance Auction Game', 'game'::resource_kind, 'Players bid limited anger coins on a list of everyday annoyances, discovering what they think is worth getting angry about.', 'Use it to help a group notice how much anger they spend on small things and choose where it is actually worth it.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Rules: each player gets ten anger coins for the whole game. The leader auctions annoyances one at a time: someone cuts in line, a sibling takes the charger, a friend is twenty minutes late, a stranger is rude online. Players bid as many coins as they think the item is worth getting angry about; the top bidder gets the item. Players who spend all ten coins early sit out the later, bigger items. Debrief on what people spent coins on, what they regretted, and how this compares with where their anger actually goes in a week. Each player writes their three worth-it items.', '[{"id": "f0", "type": "textarea", "label": "What I spent my coins on, in order:"}, {"id": "f1", "type": "textarea", "label": "Where I ran out, or what I had left at the end:"}, {"id": "f2", "type": "textarea", "label": "The annoyance I regret bidding on:"}, {"id": "f3", "type": "textarea", "label": "Where my anger actually goes in a real week, compared with the auction:"}, {"id": "f4", "type": "textarea", "label": "My three worth-it items, and what I will do with the rest:"}]'::jsonb, array['anger management', 'game', 'values']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('on-hold-customer-service-anger-thought-record', 'On Hold Customer Service Anger Thought Record', 'cbt'::resource_kind, 'A thought record for the anger that builds on hold with customer service and spills onto the person who finally answers.', 'Use it to catch the hot thoughts during a wait and plan a cooler opening line for when someone picks up.', array['Adults', 'Teens']::text[], '15 minutes, then live use', 'The hold queue is a reliable anger lab: nothing to do, a sense of being dismissed, and a person at the end who did not cause any of it. Have the client record a recent one: the thoughts at minute five, fifteen and thirty, and what came out of their mouth when a human answered. Look for mind-reading about the company and the agent, and for the belief that anger will speed things up. Then write a cooler opening line and a plan for the hold itself. Rehearse the line aloud. Ask the client to use it on the next call and report what the agent did in response.', '[{"id": "f0", "type": "textarea", "label": "The call, how long I waited, and my thoughts at minute five, fifteen and thirty:"}, {"id": "f1", "type": "textarea", "label": "What I said when a person finally answered, and how they responded:"}, {"id": "f2", "type": "textarea", "label": "The thinking traps in my hold thoughts: mind-reading, fairness rules, catastrophizing, others:"}, {"id": "f3", "type": "textarea", "label": "Whether anger has ever actually sped up a call for me:"}, {"id": "f4", "type": "textarea", "label": "My cooler opening line for the next call, and what I will do during the hold:"}, {"id": "f5", "type": "textarea", "label": "Next call: what I said, and what the agent did:"}]'::jsonb, array['anger management', 'core CBT', 'thinking traps']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('venting-payoff-versus-values-page', 'Venting Payoff Versus Values Page', 'act'::resource_kind, 'A page weighing what venting anger buys the client in the moment against what it costs the life they want.', 'Use it to help a client see the short payoff of letting anger out and choose what their values would do instead.', array['Adults', 'Teens']::text[], '20 minutes', 'Venting feels good and many clients believe it is healthy, which makes it hard to question. Ask what venting buys in the first minute: relief, feeling heard, a sense of power. Then ask what it costs by the next day: the apology, the distance, the reputation. Set these beside the client’s values about how they want to be with people. Then look for what the values would do with the same energy: a direct request, a walk, a written letter not sent. This is not an argument that anger is wrong. The emotion is welcome; the question is what to do with it.', '[{"id": "f0", "type": "textarea", "label": "What venting buys me in the first minute:"}, {"id": "f1", "type": "textarea", "label": "What it costs me by the next day:"}, {"id": "f2", "type": "textarea", "label": "How I want to be with the people I vent at, in my own words:"}, {"id": "f3", "type": "textarea", "label": "What those values would do with the same energy:"}, {"id": "f4", "type": "textarea", "label": "One moment this week where I will try the values move and see what happens:"}]'::jsonb, array['anger management', 'values', 'committed action']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('sarcasm-catch-and-replace-sheet-for-partners', 'Sarcasm Catch and Replace Sheet for Partners', 'couples'::resource_kind, 'A sheet for couples where sarcasm has become the way anger gets expressed, with a catch signal and a plain-words replacement.', 'Use it to help partners notice sarcasm as anger in disguise and say the plain thing underneath instead.', array['Couples']::text[], '30 minutes', 'Sarcasm lets anger out while denying it was there, and the receiving partner is left hurt and told they are too sensitive. Each partner writes recent sarcastic lines they said and heard, then translates each into the plain statement underneath: I am annoyed that the dishes are still there. Agree a light signal for catching it in the moment, such as a word or a raised hand, and a rule that the catch is met with the plain version, not a defense. Watch for the partner who frames sarcasm as humor; sort real jokes into a separate pile with the other partner’s agreement.', '[{"id": "f0", "type": "textarea", "label": "Partner A: sarcastic lines I have said this month, and the plain statement under each:"}, {"id": "f1", "type": "textarea", "label": "Partner B: sarcastic lines I have said this month, and the plain statement under each:"}, {"id": "f2", "type": "textarea", "label": "Lines we each heard that stung, and what we wish had been said instead:"}, {"id": "f3", "type": "textarea", "label": "Our catch signal, and what the catcher and the caught will each do:"}, {"id": "f4", "type": "textarea", "label": "Which of our lines were real jokes, and how we both know the difference:"}]'::jsonb, array['anger management', 'couples', 'communication']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('photo-as-proof-checking-habit-audit-sheet', 'Photo as Proof Checking Habit Audit Sheet', 'worksheet'::resource_kind, 'An audit of the photos a client takes of the stove, the lock or the outlet so they can check later, and what the habit has grown into.', 'Use it to make a quiet checking habit visible and plan how to let a photo go untaken.', array['Adults', 'Teens']::text[], '20 minutes, then one week', 'Photographing the stove or the locked door feels like a clever fix for checking, and it often becomes the checking: the photo gets looked at, doubted, zoomed, retaken. Have the client count the photos in their camera roll from the last month and log new ones for a week with the doubt that followed. Then plan a graded letting go: leave the house, photograph nothing, and notice the doubt rise and fall. Keep the language on urges and doubt. Clients often need to hear that the aim is tolerating not knowing, not proving the stove is off, which no photo can finally do.', '[{"id": "f0", "type": "textarea", "label": "The photos in my camera roll from the last month that were taken to check something:"}, {"id": "f1", "type": "textarea", "label": "This week’s new checking photos, and the doubt that came after each:"}, {"id": "f2", "type": "textarea", "label": "How often the photo settled the doubt, and for how long:"}, {"id": "f3", "type": "textarea", "label": "My first step: the departure where I will take no photo, and what I expect to feel:"}, {"id": "f4", "type": "textarea", "label": "What the doubt did when I left without the photo:"}]'::jsonb, array['OCD', 'self-monitoring', 'exposure']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('send-the-email-with-one-read-experiment-sheet', 'Send the Email With One Read Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment for sending an email after a single read-through instead of the usual ten, and tracking what follows.', 'Use it to test the prediction that an unreviewed email will contain a disaster, against what actually happens.', array['Adults', 'Teens']::text[], 'One week', 'Clients who reread emails many times before sending predict that one read will let a catastrophe through. Pick low-stakes emails first and have them write the prediction: what error will slip through, how the recipient will react, how sure they are. Then one read, send, and no reopening the sent folder. Record the actual reply. Over a week the client builds a record of predicted versus actual outcomes, and the rereading usually drops as the predictions fail. If an error does slip through, treat it as data: what did it cost, and was the cost anywhere near the forecast?', '[{"id": "f0", "type": "textarea", "label": "The email, and my prediction: the error that will slip through, how they will react, how sure I am:"}, {"id": "f1", "type": "textarea", "label": "One read, sent. The urge to reopen, 0 to 10, and whether I resisted:"}, {"id": "f2", "type": "textarea", "label": "The actual reply or outcome:"}, {"id": "f3", "type": "textarea", "label": "My running tally of predicted disasters versus actual ones:"}, {"id": "f4", "type": "textarea", "label": "If an error did slip through: what it cost, and how that compared with the forecast:"}]'::jsonb, array['OCD', 'behavioral experiment', 'core CBT']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('intrusive-thought-movie-trailer-defusion-page', 'Intrusive Thought Movie Trailer Defusion Page', 'act'::resource_kind, 'A defusion page that treats an intrusive thought as an over-dramatic movie trailer the mind keeps playing.', 'Use it to help a client watch an intrusive thought as a trailer, complete with voiceover, rather than as news.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to write the intrusive thought as a movie trailer: the deep voiceover, the ominous music, the one-line tagline, the release date that never comes. Reading it aloud in the trailer voice is the exercise. The point is not to mock the fear but to notice the mind’s production values and the gap between a trailer and an event. For clients with intrusive thoughts about harm, keep the frame firmly on the thought as a mental event and never on whether it means something about them; if a client voices intent rather than an intrusive thought, shift to safety, including 988 to call or text.', '[{"id": "f0", "type": "textarea", "label": "My intrusive thought written as a movie trailer, with voiceover and tagline:"}, {"id": "f1", "type": "textarea", "label": "What I noticed when I read it aloud in the trailer voice:"}, {"id": "f2", "type": "textarea", "label": "How many times this trailer has played, and how many times the movie has come out:"}, {"id": "f3", "type": "textarea", "label": "What I can do while the trailer plays in the background:"}, {"id": "f4", "type": "textarea", "label": "If a thought ever feels like a plan rather than a trailer, I will tell my clinician, and I can call or text 988:"}]'::jsonb, array['OCD', 'defusion', 'intrusive thoughts']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('messy-hands-finger-paint-mission-play', 'Messy Hands Finger Paint Mission Play', 'kids'::resource_kind, 'A child and parent finger paint together with a rule that hands stay messy until the picture is done.', 'Use it to give a child who hates mess a playful, chosen way to practice tolerating sticky hands with a parent alongside.', array['Children']::text[], '30 minutes', 'Set out finger paints and big paper. The mission: make a picture together, and hands stay painty until it is finished. Agree beforehand how the child will signal a break and that wiping before the end means the mission restarts, not that anyone is in trouble. The parent paints too, with equally messy hands, and names their own mild discomfort lightly. Debrief with the child on how the messy feeling changed over the picture. Go gently; if the child cannot start, begin with one finger and build. Keep the frame on brave play, never on contamination facts.', '[{"id": "f0", "type": "textarea", "label": "What we painted:"}, {"id": "f1", "type": "textarea", "label": "How my hands felt at the start, in the middle and at the end:"}, {"id": "f2", "type": "textarea", "label": "My break signal, and whether I used it:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up said about their own messy hands:"}, {"id": "f4", "type": "textarea", "label": "Parent: how long we lasted, what we will try next time, and what my child said after washing up:"}]'::jsonb, array['OCD', 'children', 'play']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('checking-together-habit-break-sheet-for-partners', 'Checking Together Habit Break Sheet for Partners', 'couples'::resource_kind, 'A sheet for couples where the partner has been drafted into checking the locks, the stove or the baby monitor on request.', 'Use it to help a partner step out of the checking ritual kindly and agree what they will offer instead.', array['Couples']::text[], '40 minutes', 'When one partner checks, the other often gets asked to look too, and the double check becomes part of the ritual. Map the shared checks together: which ones, how often, what the partner is asked to say. Then agree a gentle plan: the partner stops confirming, offers a warm alternative such as a hand squeeze and a stock phrase, and the checking partner names the doubt as doubt. Expect the first week to be harder for both; schedule the plan to start on a calm week. Keep the tone on urges and doubt, not on anyone being difficult.', '[{"id": "f0", "type": "textarea", "label": "The checks I ask my partner to do or confirm, and how often:"}, {"id": "f1", "type": "textarea", "label": "Partner: what being asked to check does to me, and what I would rather offer:"}, {"id": "f2", "type": "textarea", "label": "Our stock phrase for when the ask comes, and the warm alternative that goes with it:"}, {"id": "f3", "type": "textarea", "label": "The week we will start, and what each of us expects the first days to be like:"}, {"id": "f4", "type": "textarea", "label": "What we each noticed in the first week, and what we will adjust:"}]'::jsonb, array['OCD', 'couples', 'support']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('scary-and-safe-at-once-both-and-card', 'Scary and Safe at Once Both-And Card', 'dbt'::resource_kind, 'A dialectical card for holding two truths during a panic surge: this feels terrifying, and I am not in danger.', 'Use it to give a client a both-and statement to carry through a surge instead of arguing one side against the other.', array['Adults', 'Teens']::text[], 'Five minutes to write, then carried', 'Clients in panic often swing between this is an emergency and I am being ridiculous, and both extremes make it worse. Walking the middle path offers both-and: my body is in full alarm, and I am safe in this room. Write three such statements with the client, each with a true feeling half and a true fact half, in their own words. Practice saying one slowly on the out-breath during a mild surge in session if one arises, or after a brief sensation exercise. The card goes in the wallet or phone case. Check that the fact half is something the client actually believes when calm, or it will not hold.', '[{"id": "f0", "type": "textarea", "label": "Three both-and statements in my own words, each with a true feeling half and a true fact half:"}, {"id": "f1", "type": "textarea", "label": "The one I will carry, and where it will live:"}, {"id": "f2", "type": "textarea", "label": "A surge this week where I said it on the out-breath, and what happened:"}, {"id": "f3", "type": "textarea", "label": "Which half was harder to believe in the moment, and what would make it easier:"}, {"id": "f4", "type": "textarea", "label": "What changed when I stopped arguing one half against the other:"}]'::jsonb, array['panic attacks', 'core DBT', 'distress tolerance']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('lingering-sensations-after-panic-thought-check-sheet', 'Lingering Sensations After Panic Thought Check Sheet', 'cbt'::resource_kind, 'A thought check for the shaky, unreal, wrung-out feelings in the hours after a panic surge and what the client makes of them.', 'Use it to help a client read the aftermath of a surge as the body settling rather than as proof something is still wrong.', array['Adults', 'Teens']::text[], '15 minutes', 'The surge passes, but the hours after can bring trembling, a floaty unreal feeling, exhaustion and a hair-trigger body, and many clients read these as a sign the attack is not over or that something has been damaged. Record the lingering sensations, the thought about each, and the alternative that a body which has just run a full alarm takes time to settle. Plan what the client will do in the aftermath hours: gentle activity rather than scanning. If the aftermath includes anything the client has not had checked medically, encourage that visit plainly.', '[{"id": "f0", "type": "textarea", "label": "The sensations that lingered after my last surge, and for how long:"}, {"id": "f1", "type": "textarea", "label": "What I made of each one in the moment:"}, {"id": "f2", "type": "textarea", "label": "Another way to read the same sensations, given what my body had just done:"}, {"id": "f3", "type": "textarea", "label": "A time my body felt similar after something ordinary, like exertion or a near miss:"}, {"id": "f4", "type": "textarea", "label": "What I will do in the hours after the next surge instead of scanning:"}]'::jsonb, array['panic attacks', 'core CBT', 'thinking traps']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('life-without-the-escape-route-values-page', 'Life Without the Escape Route Values Page', 'act'::resource_kind, 'A values page listing the places the client only enters with an exit planned, and what living there would be like without the escape route.', 'Use it to connect dropping the escape plan to the life the client wants rather than to proving panic wrong.', array['Adults', 'Teens']::text[], '25 minutes', 'Many clients attend everything but only with an aisle seat, a car parked nearby, a bottle of water and a reason to leave ready. Map the escape routes honestly, without judgment. Then ask what each one costs: attention, presence, spontaneity, the friend who is never told why. Connect each place to a value, and ask what being fully there would look like. Choose one event to attend with one escape route deliberately absent, as a willingness step toward the value rather than as a test of whether panic comes. Debrief on presence, not on whether a surge happened.', '[{"id": "f0", "type": "textarea", "label": "The places I go only with an escape route, and what the route is in each:"}, {"id": "f1", "type": "textarea", "label": "What the escape routes cost me in attention, presence and honesty:"}, {"id": "f2", "type": "textarea", "label": "The value each place connects to, in my own words:"}, {"id": "f3", "type": "textarea", "label": "One event this week I will attend with one escape route deliberately absent:"}, {"id": "f4", "type": "textarea", "label": "Afterward: how present I was, whatever my body did:"}]'::jsonb, array['panic attacks', 'values', 'willingness']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('partner-step-back-plan-for-going-out-alone', 'Partner Step-Back Plan for Going Out Alone', 'couples'::resource_kind, 'A graded plan for the partner who has become the client’s safe person to step back so the client can go out alone again.', 'Use it to help a couple loosen a safe-person arrangement in agreed steps without either feeling abandoned or pushed.', array['Couples']::text[], '40 minutes', 'When one partner has panic, the other often becomes the safe person, and errands, drives and events stop happening without them. Both describe the arrangement and what it costs each of them. Then build steps: partner waits in the car, partner is on text, partner is reachable but not told the time, partner is out of contact for an hour. The client sets the order and pace; the partner agrees what they will and will not do at each step, including not rescuing early. Plan what each will say if a surge happens mid-step. Review weekly and move only when the current step is dull.', '[{"id": "f0", "type": "textarea", "label": "Partner with panic: where I no longer go alone, and what having my partner there does for me:"}, {"id": "f1", "type": "textarea", "label": "Supporting partner: what being the safe person costs me, and what I worry about if I step back:"}, {"id": "f2", "type": "textarea", "label": "Our steps, from the smallest step back to the largest, in the order the partner with panic chooses:"}, {"id": "f3", "type": "textarea", "label": "What the supporting partner will and will not do at each step, including when a surge happens:"}, {"id": "f4", "type": "textarea", "label": "This week’s step, and how it went for both of us:"}]'::jsonb, array['panic attacks', 'couples', 'exposure']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('body-sensation-bingo-group-game', 'Body Sensation Bingo Group Game', 'game'::resource_kind, 'A bingo game where squares are ordinary body sensations the group produces on purpose with quick, safe activities.', 'Use it to help a group get friendly with the sensations that show up in panic by making them on purpose and laughing.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Rules: each player has a bingo card of sensations: warm face, fast heart, tingling hands, dizzy, breathless, dry mouth. The leader calls activities (twenty jumping jacks, spin three times, breathe fast for thirty seconds, hold breath for twenty, stare at a bright light) and players mark any sensation they notice. First to a line calls bingo and reads their line aloud. Debrief: which sensations also show up in panic, how long each took to fade, and what it was like to make them on purpose in a room full of people. Check health considerations before the activities and let anyone sit out any one.', '[{"id": "f0", "type": "textarea", "label": "The sensations I marked and which activity produced each:"}, {"id": "f1", "type": "textarea", "label": "How long each took to fade, roughly:"}, {"id": "f2", "type": "textarea", "label": "Which of these show up in my panic, and what I usually make of them then:"}, {"id": "f3", "type": "textarea", "label": "What it was like to make them on purpose in a group:"}, {"id": "f4", "type": "textarea", "label": "One activity I could use at home to practice with a sensation:"}]'::jsonb, array['panic attacks', 'game', 'exposure']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('default-parent-rebalance-sheet', 'Default Parent Rebalance Sheet', 'couples'::resource_kind, 'A sheet for couples where one parent has become the one the school, the pediatrician and the kids call first.', 'Use it to name the default-parent pattern and move specific responsibilities, not just tasks, to the other parent.', array['Couples']::text[], '45 minutes', 'In many households one parent becomes the default: the one who knows the shoe size, the dentist, the field trip date, and the one the child shouts for. The default parent lists the invisible responsibilities they hold, including knowing things, not just doing them. The other parent chooses two or three to own fully, meaning the knowing and the deciding, not just the doing when asked. Agree how the children and the school will learn who to call. Watch for the default parent correcting or re-taking the task in the first weeks, and for the other parent waiting to be told. Review in a month.', '[{"id": "f0", "type": "textarea", "label": "Default parent: the responsibilities I hold, including the knowing, not just the doing:"}, {"id": "f1", "type": "textarea", "label": "Other parent: the two or three I will own fully, knowing and deciding included:"}, {"id": "f2", "type": "textarea", "label": "How the kids, the school and the pediatrician will learn who to call for those:"}, {"id": "f3", "type": "textarea", "label": "Default parent: what I will do when I want to correct or take it back:"}, {"id": "f4", "type": "textarea", "label": "Other parent: what I will do when I am tempted to wait to be told:"}, {"id": "f5", "type": "textarea", "label": "Our one-month review date:"}]'::jsonb, array['parenting', 'couples', 'family']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('bedtime-routine-train-cars-craft', 'Bedtime Routine Train Cars Craft', 'kids'::resource_kind, 'A child makes a paper train where each car is a bedtime step, and moves the engine along as each one is done.', 'Use it to turn a fought-over bedtime into a sequence the child can see and drive themselves.', array['Children']::text[], '30 minutes to make', 'Cut a paper engine and five or six cars. The child draws a bedtime step on each: bath, pajamas, teeth, book, hug, lights. Tape the cars in order on the wall at child height and let the child move a clothespin engine along as each step is done. The parent’s job is to say which car we are on rather than to issue orders, and to let the child drive the engine. Keep the train the same every night for two weeks before changing anything. Children who resist bedtime often resist being told; the train tells them instead. The last car can be a special one that only appears when the engine arrives.', '[{"id": "f0", "type": "textarea", "label": "My bedtime cars, in order:"}, {"id": "f1", "type": "textarea", "label": "The car that is hardest for me:"}, {"id": "f2", "type": "textarea", "label": "What my grown-up says instead of telling me what to do:"}, {"id": "f3", "type": "textarea", "label": "The special last car and what happens when the engine gets there:"}, {"id": "f4", "type": "textarea", "label": "Parent: how bedtime went this week with the train, and what we kept the same:"}]'::jsonb, array['parenting', 'children', 'routines']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('chore-charades-family-game', 'Chore Charades Family Game', 'game'::resource_kind, 'A family game where players mime a household chore and the family guesses it, then decides together who does it this week.', 'Use it to get a family talking about the household load with laughter before anyone gets defensive.', array['Children', 'Teens', 'Adults']::text[], '25 minutes', 'Rules: write every household chore on a slip, including the invisible ones like noticing we are out of milk. Players draw a slip and mime it; the family guesses. Each guessed chore goes on the board, and once the pile is done the family looks at the board and asks who does this now and who could. Children often discover chores they never knew existed, and parents often discover they disagree about who does them. Debrief with a simple plan for the week and one chore that will rotate. Keep the game light, and let a child pick a parent’s chore to try.', '[{"id": "f0", "type": "textarea", "label": "The chores we mimed, including the invisible ones:"}, {"id": "f1", "type": "textarea", "label": "Chores I did not know existed until the game:"}, {"id": "f2", "type": "textarea", "label": "Who does each chore now, and who could:"}, {"id": "f3", "type": "textarea", "label": "The chore I will take this week, and the one that will rotate:"}, {"id": "f4", "type": "textarea", "label": "What was funny, and what surprised us:"}]'::jsonb, array['parenting', 'game', 'family']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('public-meltdown-audience-thoughts-sheet', 'Public Meltdown Audience Thoughts Sheet', 'cbt'::resource_kind, 'A thought check for what a parent believes the onlookers are thinking during a child’s meltdown in a store or a restaurant.', 'Use it to help a parent separate their child’s moment from an imagined audience’s verdict and act on the child instead.', array['Adults']::text[], '20 minutes', 'During a public meltdown many parents respond to the imagined audience rather than to the child, and the result is a harsher parent than they want to be. Have them replay a recent one: what they believed strangers were thinking, how sure they were, and what they did because of it. Then check: what do they think when they see another parent in the same spot, what did anyone actually say, and what would they have done if the room were empty. End with a short script for the parent’s own mind in the moment. The child’s behavior is not the subject of this sheet; the parent’s audience is.', '[{"id": "f0", "type": "textarea", "label": "The meltdown: where, and what I believed the people around us were thinking:"}, {"id": "f1", "type": "textarea", "label": "How sure I was, 0 to 100, and what I did because of it:"}, {"id": "f2", "type": "textarea", "label": "What I actually think when I see another parent in that spot:"}, {"id": "f3", "type": "textarea", "label": "What anyone actually said or did, as opposed to what I imagined:"}, {"id": "f4", "type": "textarea", "label": "What I would have done if the room were empty:"}, {"id": "f5", "type": "textarea", "label": "My one-line script for my own mind next time:"}]'::jsonb, array['parenting', 'core CBT', 'thinking traps']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('playground-boredom-willingness-page', 'Playground Boredom Willingness Page', 'act'::resource_kind, 'A willingness page for the long, dull stretches of parenting that a parent feels guilty for not enjoying.', 'Use it to help a parent make room for boredom at the playground as part of showing up rather than a failure of love.', array['Adults']::text[], '15 minutes', 'Many parents are ashamed of how bored they are by pushing a swing for forty minutes, and either escape into the phone or beat themselves up for wanting to. Normalize the boredom as a feeling, not a verdict. Ask what the mind says about a parent who is bored, and what the parent values about being at the playground anyway: presence, availability, the child looking up and finding them there. Plan a willingness stance for the next long stretch: boredom allowed, phone away for an agreed window, attention returned to one small thing about the child each time it wanders.', '[{"id": "f0", "type": "textarea", "label": "The parenting stretches that bore me most, honestly:"}, {"id": "f1", "type": "textarea", "label": "What my mind says about a parent who feels bored:"}, {"id": "f2", "type": "textarea", "label": "What I value about being there anyway, in my own words:"}, {"id": "f3", "type": "textarea", "label": "My willingness plan for the next long stretch: the window, the phone, where I will return my attention:"}, {"id": "f4", "type": "textarea", "label": "What my child did when they looked up and found me there:"}]'::jsonb, array['parenting', 'willingness', 'values']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('shake-out-the-jitters-noodle-dance-play', 'Shake Out the Jitters Noodle Dance Play', 'kids'::resource_kind, 'A child and parent shake out nervous energy like wet noodles, one limb at a time, then go still and notice what is left.', 'Use it to give a worried child a body-first way to move anxiety through and out, with a parent doing it too.', array['Children']::text[], 'Five minutes, as needed', 'Put on a short song. Call each part in turn: shake the right hand like a noodle, then the arm, the other arm, each leg, the whole body, the face, until the song ends. Then freeze, hands on belly, and ask what the body feels like now compared with before. The parent shakes alongside, looking just as silly, which gives the child permission. Teach it as a thing the family does before hard moments, such as the walk into school, and not only in a crisis. Children who are self-conscious can do a hands-only version under the table. Keep it light; the laughing is part of the shaking.', '[{"id": "f0", "type": "textarea", "label": "The part of me that had the most jitters to shake out:"}, {"id": "f1", "type": "textarea", "label": "What my body felt like when we froze at the end:"}, {"id": "f2", "type": "textarea", "label": "The hard moment we will do the noodle dance before this week:"}, {"id": "f3", "type": "textarea", "label": "A time I did a secret hands-only version:"}, {"id": "f4", "type": "textarea", "label": "Parent: how I shook alongside, and what I noticed in my child afterward:"}]'::jsonb, array['anxiety', 'children', 'regulation']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('low-mood-myth-or-fact-buzzer-game', 'Low Mood Myth or Fact Buzzer Game', 'game'::resource_kind, 'Teams buzz in on statements about low mood and sort them into myth or fact, then explain the reasoning.', 'Use it to surface the beliefs a group holds about low mood and let members correct each other instead of being told.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Rules: read statements one at a time (you have to feel motivated before you can act; resting and doing nothing are the same thing; a bad morning means a bad day; small tasks do not count). Teams buzz in, call myth or fact, and must give a reason to score; a bare answer scores nothing. Where the group disagrees, let them argue it out for a minute before weighing in. Keep statements to everyday beliefs rather than medical claims, and do not introduce statistics. Debrief with each player naming one statement they had believed and what they will try instead this week.', '[{"id": "f0", "type": "textarea", "label": "The statements I was sure about, and whether the group agreed:"}, {"id": "f1", "type": "textarea", "label": "A statement I had believed that turned out to be a myth for me:"}, {"id": "f2", "type": "textarea", "label": "The best reason someone else gave, and why it landed:"}, {"id": "f3", "type": "textarea", "label": "The statement I am still not sure about:"}, {"id": "f4", "type": "textarea", "label": "What I will try this week based on one of the myths:"}]'::jsonb, array['depression', 'game', 'thinking traps']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('pregnancy-worries-between-checkups-holding-sheet', 'Pregnancy Worries Between Checkups Holding Sheet', 'worksheet'::resource_kind, 'A holding sheet for the worries that pile up between prenatal appointments, sorted into ask, act and let sit.', 'Use it to give an expecting client somewhere to put the week’s worries so they reach the appointment instead of the search bar.', array['Adults']::text[], 'Ongoing between appointments', 'Between checkups, worries about the pregnancy have nowhere to go and often end up in late-night searches that make them worse. The client writes each worry as it comes, then sorts it: a question for the next appointment, something with an action now such as calling the nurse line, or something to let sit until the visit. Agree what counts as a call-now item so the sheet never delays real care. Review the sheet in session for patterns and for the worries that return. The point is a place to put things, not a promise that the appointment will settle them all.', '[{"id": "f0", "type": "textarea", "label": "Worries that came up this week, as they arrived:"}, {"id": "f1", "type": "textarea", "label": "Which are questions for my next appointment:"}, {"id": "f2", "type": "textarea", "label": "Which need an action now, such as calling the nurse line, and what counts as call-now for me:"}, {"id": "f3", "type": "textarea", "label": "Which I can let sit until the visit, and how I will remind myself they are on the sheet:"}, {"id": "f4", "type": "textarea", "label": "The worries that keep coming back, and what I notice about when they show up:"}]'::jsonb, array['perinatal and postpartum', 'worry', 'planning']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('everyone-said-it-would-be-magical-gap-sheet', 'Everyone Said It Would Be Magical Gap Sheet', 'cbt'::resource_kind, 'A sheet that lays the stories a new parent was told about this time beside what the days actually hold.', 'Use it to help a new parent see the gap between the promised magic and the real days as a gap in the story, not in them.', array['Adults']::text[], '20 minutes', 'New parents who were promised instant joy often conclude that the problem is them when the days are mostly laundry, soreness and fog. List the specific promises they were given and by whom, then the honest content of an ordinary current day. Look at the gap and ask whose account was wrong. Then check the thought that follows the gap, usually some version of other parents feel the magic and I do not, against what other parents actually say when asked honestly. End by naming one real moment from the week that was good, without requiring it to be magical.', '[{"id": "f0", "type": "textarea", "label": "The promises I was given about this time, and who gave them:"}, {"id": "f1", "type": "textarea", "label": "What an ordinary day actually holds right now, honestly:"}, {"id": "f2", "type": "textarea", "label": "The thought I have about myself when I look at the gap:"}, {"id": "f3", "type": "textarea", "label": "What other parents actually say when I ask them honestly:"}, {"id": "f4", "type": "textarea", "label": "One real moment this week that was good, magical or not:"}]'::jsonb, array['perinatal and postpartum', 'core CBT', 'thinking traps']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('give-skill-for-unsolicited-advice-card', 'GIVE Skill for Unsolicited Advice Card', 'dbt'::resource_kind, 'A GIVE card for responding to relatives and strangers who tell a new parent how to feed, hold or settle their baby.', 'Use it to help a new parent keep the relationship and their own footing when advice arrives uninvited.', array['Adults']::text[], '10 minutes to prepare, then live use', 'Unsolicited advice about the baby lands hard on a tired parent, and the usual options are to snap or to swallow it. GIVE offers a middle: be gentle, act interested, validate what is true in the advice, use an easy manner, and then close with a short line that keeps the decision theirs. Write the client’s three most common advice-givers and the line for each, and rehearse the tone, which does most of the work. Pair with FAST if the client is losing self-respect in these exchanges. Remind them that keeping a relationship is one goal and that not every piece of advice deserves a response at all.', '[{"id": "f0", "type": "textarea", "label": "The advice I hear most, and from whom:"}, {"id": "f1", "type": "textarea", "label": "What I usually do: snap, swallow it, or something else, and what that costs:"}, {"id": "f2", "type": "textarea", "label": "My GIVE line for each person: gentle, interested, validating, easy, and ending with the decision as mine:"}, {"id": "f3", "type": "textarea", "label": "A time this week I used it, and how the other person responded:"}, {"id": "f4", "type": "textarea", "label": "Advice that does not deserve a response at all, and what I will do instead:"}]'::jsonb, array['perinatal and postpartum', 'core DBT', 'interpersonal effectiveness']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('baby-milestone-pressure-defusion-page', 'Baby Milestone Pressure Defusion Page', 'act'::resource_kind, 'A defusion page for the running commentary about whether the baby is rolling, smiling or sleeping on schedule.', 'Use it to help a new parent notice the milestone tracker in their head as a thought stream and return to the baby in front of them.', array['Adults']::text[], '15 minutes', 'Apps and relatives hand a new parent a timetable, and the mind runs it constantly: she should be rolling by now. Have the parent write the commentary as it sounds, then practice saying each line with the words I am having the thought that in front. Ask what the commentary pulls them away from, usually the actual baby. Plan one ten-minute stretch a day of watching the baby with the tracker noticed and set aside. This page does not replace a pediatrician’s guidance; if a parent has a specific concern, encourage them to raise it at the next visit and set it down between visits.', '[{"id": "f0", "type": "textarea", "label": "The milestone commentary my mind runs, in its own words:"}, {"id": "f1", "type": "textarea", "label": "The same lines with I am having the thought that in front:"}, {"id": "f2", "type": "textarea", "label": "What the commentary pulls my attention away from:"}, {"id": "f3", "type": "textarea", "label": "My ten minutes of watching the baby today, and what the baby actually did:"}, {"id": "f4", "type": "textarea", "label": "A specific question I will raise at the next pediatric visit, so I can set it down until then:"}]'::jsonb, array['perinatal and postpartum', 'defusion', 'mindfulness']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('grandparent-help-boundaries-talk-sheet-for-new-parents', 'Grandparent Help Boundaries Talk Sheet for New Parents', 'couples'::resource_kind, 'A talk sheet for new parents to agree together what help they want from grandparents and what they will say about the rest.', 'Use it to get a couple on the same page about grandparent involvement before either one has the hard conversation alone.', array['Couples']::text[], '40 minutes', 'Grandparent help is a gift that often arrives with opinions, and new parents frequently disagree about it along family lines: one partner defends their parents, the other feels outnumbered. Each partner writes what help they want, what they do not, and what is non-negotiable for the baby’s care. Compare and find the shared position. Then decide who speaks to which grandparent, since each partner handling their own family usually works best, and write the actual sentences. Revisit when the arrangement changes, such as a return to work.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the help I want from grandparents, the help I do not, and what is non-negotiable:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the help I want from grandparents, the help I do not, and what is non-negotiable:"}, {"id": "f2", "type": "textarea", "label": "Our shared position, in a few sentences we both agree with:"}, {"id": "f3", "type": "textarea", "label": "Who speaks to which grandparent, and the sentences they will use:"}, {"id": "f4", "type": "textarea", "label": "What each of us will do when a grandparent pushes back:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'boundaries']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('yes-i-did-that-accomplishment-trivia-game', 'Yes I Did That Accomplishment Trivia Game', 'game'::resource_kind, 'A team trivia game where the questions are real accomplishments of group members and players guess who did each one.', 'Use it to let group members hear their own accomplishments read aloud and claimed in front of others.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Rules: before the game, each member writes three accomplishments on slips, small or large, with their name on the back. The leader reads a slip; teams confer and guess who did it, scoring a point for a correct guess. The owner then says yes, I did that, out loud, and adds one sentence about it. No deflecting allowed; a shrugged-off accomplishment costs the owner’s team a point. Debrief on what it was like to claim something aloud, which accomplishments surprised the group, and what people noticed in their body when their slip was read. Members keep their slips.', '[{"id": "f0", "type": "textarea", "label": "My three accomplishments, as I wrote them:"}, {"id": "f1", "type": "textarea", "label": "What my body did when my slip was read:"}, {"id": "f2", "type": "textarea", "label": "What it was like to say yes, I did that without deflecting:"}, {"id": "f3", "type": "textarea", "label": "An accomplishment of someone else’s that surprised me, and what it told me about guessing:"}, {"id": "f4", "type": "textarea", "label": "The slip I will keep where I can see it:"}]'::jsonb, array['self-esteem', 'game', 'strengths']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('proud-moments-photo-frame-craft', 'Proud Moments Photo Frame Craft', 'kids'::resource_kind, 'A child decorates a frame and chooses, with a parent, a picture or drawing of a moment they were proud of to put inside.', 'Use it to give a child a visible reminder of something they did, chosen by them and talked through with a parent.', array['Children']::text[], '30 minutes', 'Decorate a cardboard frame with paint, stickers and the child’s name. Then the child picks a proud moment: a photo if there is one, or a drawing of the moment if there is not. The parent asks what made it proud rather than praising, and writes the child’s words on the back. The frame goes where the child sees it daily, and the picture changes monthly so the child collects proud moments over time. Steer away from frames for trophies and grades alone; a moment of kindness or of trying something hard belongs here too. Keep the old pictures in an envelope on the back.', '[{"id": "f0", "type": "textarea", "label": "The proud moment I chose, and why it was proud:"}, {"id": "f1", "type": "textarea", "label": "What I drew or which photo I picked:"}, {"id": "f2", "type": "textarea", "label": "My words about it that my grown-up wrote on the back:"}, {"id": "f3", "type": "textarea", "label": "Where my frame lives:"}, {"id": "f4", "type": "textarea", "label": "Parent: what I asked instead of praising, and what my child said:"}]'::jsonb, array['self-esteem', 'children', 'craft']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('if-they-really-knew-me-thought-check-sheet', 'If They Really Knew Me Thought Check Sheet', 'cbt'::resource_kind, 'A thought check for the belief that people only like the client because they do not know the real person underneath.', 'Use it to test the hidden-self belief against what the people closest to the client already know and still do.', array['Adults', 'Teens']::text[], '20 minutes', 'The belief that one is liked only by mistake sits under a great deal of low self-worth. Write the thought exactly: if they really knew me, they would. Then list the people who know the client best and what each of them actually knows, including the things the client is ashamed of. Many clients find that the people closest to them already know the worst and are still there. Then ask what the belief predicts about new people and whether that prediction has ever been tested. End with one small disclosure to a safe person, chosen by the client, as a next experiment.', '[{"id": "f0", "type": "textarea", "label": "The thought, exactly: if they really knew me, they would:"}, {"id": "f1", "type": "textarea", "label": "The people who know me best, and what each of them actually knows about me:"}, {"id": "f2", "type": "textarea", "label": "Which of the things I hide they already know, and what they did with that knowledge:"}, {"id": "f3", "type": "textarea", "label": "What the belief predicts about new people, and whether I have ever tested it:"}, {"id": "f4", "type": "textarea", "label": "One small true thing I am willing to let a safe person know this week:"}]'::jsonb, array['self-esteem', 'core CBT', 'thinking traps']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('hand-on-heart-self-kindness-exercise-page', 'Hand on Heart Self-Kindness Exercise Page', 'act'::resource_kind, 'A brief self-compassion practice of placing a hand on the chest and speaking to oneself as one would to a struggling friend.', 'Use it to give a self-critical client a physical, repeatable way to meet a hard moment with kindness.', array['Adults', 'Teens']::text[], 'Two minutes, several times a day', 'Practice in session first. The client places a hand flat on their chest, feels the warmth and the pressure, takes a slow breath and says, silently or aloud, what they would say to a friend in this exact spot. Many self-critical clients feel awkward or undeserving; name that as the mind doing its job and continue. Ask them to notice the body’s response to the touch separately from the mind’s commentary. For homework, three times a day at hard moments, with the sentence written on the page. Clients who dislike chest contact can hold their own hand or forearm.', '[{"id": "f0", "type": "textarea", "label": "The sentence I would say to a friend in my exact spot:"}, {"id": "f1", "type": "textarea", "label": "What my body noticed with my hand on my chest:"}, {"id": "f2", "type": "textarea", "label": "What my mind said about doing this, and what I did with that:"}, {"id": "f3", "type": "textarea", "label": "Three hard moments this week where I used it:"}, {"id": "f4", "type": "textarea", "label": "What changed, if anything, in how the moment went:"}]'::jsonb, array['self-esteem', 'self-compassion', 'core ACT']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('accomplishment-resume-page', 'Accomplishment Resume Page', 'worksheet'::resource_kind, 'A one-page resume of the client’s life accomplishments, including the kind that never appear on a job application.', 'Use it to build a client a document of what they have actually done, to read on the days their mind says nothing.', array['Adults', 'Teens']::text[], '40 minutes in session, then added to', 'Set the page up like a resume with sections: things I built or finished, hard things I got through, people I showed up for, skills I taught myself, times I did the right thing when nobody saw. Fill it with the client, pressing for specifics and dates where possible. Clients will discount most items; write them down anyway and discuss the discounting afterward. The finished page is a document, not an affirmation, and it should read like one. Ask them to add one line a month and to read it on the days the mind files everything under nothing. Teens may want a version they can show a parent.', '[{"id": "f0", "type": "textarea", "label": "Things I built, made or finished:"}, {"id": "f1", "type": "textarea", "label": "Hard things I got through:"}, {"id": "f2", "type": "textarea", "label": "People I showed up for, and how:"}, {"id": "f3", "type": "textarea", "label": "Skills I taught myself:"}, {"id": "f4", "type": "textarea", "label": "Times I did the right thing when nobody was watching:"}, {"id": "f5", "type": "textarea", "label": "The items I wanted to leave off, and the reason I gave:"}]'::jsonb, array['self-esteem', 'strengths', 'self-monitoring']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('listen-instead-of-rehearsing-my-line-card', 'Listen Instead of Rehearsing My Line Card', 'dbt'::resource_kind, 'A mindfulness-of-others card for putting attention on what the other person is saying rather than on the sentence being prepared.', 'Use it to help a socially anxious client stop rehearsing their next line and actually hear the conversation.', array['Adults', 'Teens']::text[], 'Live use in conversations, one week', 'Clients with social anxiety often spend conversations composing and editing their next sentence, then miss what was said and feel even more out of step. The card asks them to put attention on the other person’s words, face and tone, to notice when it drifts to rehearsal, and to bring it back, accepting that the reply will be less polished. Practice in session with you talking about something ordinary and the client raising a finger each time they catch themselves rehearsing. For homework, three conversations with a quick note afterward.', '[{"id": "f0", "type": "textarea", "label": "How often I caught myself rehearsing in a practice conversation, and what I was composing:"}, {"id": "f1", "type": "textarea", "label": "Three conversations this week where I used the card:"}, {"id": "f2", "type": "textarea", "label": "What I heard that I would normally have missed:"}, {"id": "f3", "type": "textarea", "label": "How the unrehearsed replies landed, as far as I could tell:"}, {"id": "f4", "type": "textarea", "label": "What my mind said about replying without a script, and what actually happened:"}]'::jsonb, array['social anxiety', 'core DBT', 'mindfulness']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('leaving-the-party-signal-agreement-for-partners', 'Leaving the Party Signal Agreement for Partners', 'couples'::resource_kind, 'An agreement for couples where one partner needs to leave events earlier than the other, with a signal and a plan both accept.', 'Use it to stop the silent standoff at the end of every gathering and give both partners a known way to end the night.', array['Couples']::text[], '30 minutes', 'The socially anxious partner watches the clock; the other is just getting started; neither says anything until the car ride. Each describes what the end of an event is like for them. Then agree a quiet signal for I am ready, a check-in that follows it, and the options: leave together, one leaves and one stays with a ride home arranged, or a fifteen-minute wind-down. Also agree the maximum stay before the event, so the anxious partner is not negotiating from inside their anxiety. Watch for the signal becoming a demand or being ignored; both are worth a line on the sheet.', '[{"id": "f0", "type": "textarea", "label": "Partner who leaves early: what the end of an event is like for me, and what I usually do:"}, {"id": "f1", "type": "textarea", "label": "Partner who stays late: what it is like when my partner wants to leave, and what I usually do:"}, {"id": "f2", "type": "textarea", "label": "Our quiet signal, and the check-in that follows it:"}, {"id": "f3", "type": "textarea", "label": "Our options when the signal comes: leave together, split with a ride, or a fifteen-minute wind-down:"}, {"id": "f4", "type": "textarea", "label": "How we will set the maximum stay before we arrive, and what we will say if the agreement slips:"}]'::jsonb, array['social anxiety', 'couples', 'communication']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('order-my-own-snack-brave-mission-card', 'Order My Own Snack Brave Mission Card', 'kids'::resource_kind, 'A mission card for a child to order their own snack or drink from a counter, with a parent standing one step back.', 'Use it to give a shy child a small, real speaking task with a clear script and a parent who does not take over.', array['Children']::text[], '15 minutes to prepare, then the outing', 'Write the mission on the card with the child: what they will order, the words they will say, and what they will do if the person did not hear. Practice it twice as a game at home with the parent as the server. On the outing, the parent stands one step behind, does not speak for the child, and waits through the pause, which is the hardest part for the parent. Afterward, the child colors in the mission star and the parent asks what the server did rather than praising bravery in general. Build up over weeks: a snack, then asking where the bathroom is, then asking a question of a teacher.', '[{"id": "f0", "type": "textarea", "label": "My mission: what I will order and the words I will say:"}, {"id": "f1", "type": "textarea", "label": "What I will do if they did not hear me:"}, {"id": "f2", "type": "textarea", "label": "How we practiced at home:"}, {"id": "f3", "type": "textarea", "label": "What the server did when I ordered:"}, {"id": "f4", "type": "textarea", "label": "Parent: how I managed to wait through the pause, and what we will try next:"}]'::jsonb, array['social anxiety', 'children', 'exposure']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('shaky-voice-noticeability-experiment-sheet', 'Shaky Voice Noticeability Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment testing how noticeable a shaky voice actually is to listeners compared with how it feels from inside.', 'Use it to help a client check the belief that everyone can hear their voice shaking against listeners’ real reports.', array['Adults', 'Teens']::text[], 'One session plus one week', 'From the inside a shaky voice feels like a siren; the question is what listeners hear. In session, record the client speaking for a minute while anxious and have them rate the shakiness they felt. Then listen together and rate what is audible. Next, with permission, have the client ask one or two trusted people after a conversation whether they noticed anything about their voice, with the prediction written beforehand. Most clients find the gap large. If the voice is in fact audibly shaky at times, work on whether that is as costly as feared rather than on hiding it.', '[{"id": "f0", "type": "textarea", "label": "How shaky my voice felt from inside, 0 to 10, and the situation:"}, {"id": "f1", "type": "textarea", "label": "What I heard when we listened back, 0 to 10, and what I noticed:"}, {"id": "f2", "type": "textarea", "label": "My prediction of what a trusted listener would report:"}, {"id": "f3", "type": "textarea", "label": "What the listener actually said when I asked:"}, {"id": "f4", "type": "textarea", "label": "The gap between felt, heard and reported, and what I make of it:"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'core CBT']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('introversion-or-avoidance-honest-sort-page', 'Introversion or Avoidance Honest Sort Page', 'act'::resource_kind, 'A sorting page that separates the quiet a client genuinely prefers from the quiet that is fear in disguise.', 'Use it to help a client tell preference from avoidance so they can protect the first and move toward values in the second.', array['Adults', 'Teens']::text[], '25 minutes', 'Many socially anxious clients describe themselves as introverts, and some are; the sort is not a judgment either way. List the social things the client skipped this month. For each, ask two questions: would I want this if the fear were gone, and what did skipping it cost me in terms of what I care about. Genuine preference passes both: no desire, no cost. Avoidance fails at least one. Protect the preferences openly, and pick one avoidance item as a willingness step toward its value. Revisit the sort every few weeks as the picture changes.', '[{"id": "f0", "type": "textarea", "label": "Social things I skipped this month:"}, {"id": "f1", "type": "textarea", "label": "For each: would I want it if the fear were gone, yes or no:"}, {"id": "f2", "type": "textarea", "label": "For each: what skipping it cost me in what I care about, if anything:"}, {"id": "f3", "type": "textarea", "label": "The ones that are real preferences, which I will keep without apology:"}, {"id": "f4", "type": "textarea", "label": "The one avoidance item I will move toward this week, and the value it serves:"}]'::jsonb, array['social anxiety', 'values', 'willingness']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('questions-about-death-jar-craft', 'Questions About Death Jar Craft', 'kids'::resource_kind, 'A child decorates a jar for the questions they have about death and the person who died, which a parent answers one at a time.', 'Use it to give a grieving child a way to ask hard questions at their own pace and a parent a way to answer honestly.', array['Children']::text[], '30 minutes to make, then ongoing', 'Children grieve in bursts and ask the big questions at odd moments, often when the parent is least ready. The jar gives both a place to put them. The child decorates it; the parent agrees to pull one question a day, or when the child asks, and to answer honestly, briefly and in plain words, saying I do not know when that is the truth. Coach the parent on the plain words: died, dead, body stopped working, rather than lost or sleeping. Reassure the parent that short true answers are enough and the child will ask again. If a question reveals a safety concern, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The questions I put in my jar so far:"}, {"id": "f1", "type": "textarea", "label": "The question we pulled today, and what my grown-up said:"}, {"id": "f2", "type": "textarea", "label": "A question I am still thinking about:"}, {"id": "f3", "type": "textarea", "label": "Something I want to remember about the person:"}, {"id": "f4", "type": "textarea", "label": "Parent: the plain words I am using, and what I said when I did not know:"}]'::jsonb, array['grief and loss', 'children', 'family']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('what-they-taught-me-round-robin-game', 'What They Taught Me Round Robin Game', 'game'::resource_kind, 'A grief group game where players name one thing the person they lost taught them, and the group guesses what that person was like.', 'Use it to help a group speak about the people they have lost through what those people left behind in them.', array['Groups', 'Adults', 'Teens']::text[], '30 minutes', 'Rules: in turn, each player names one thing the person they lost taught them, from how to fold a map to how to apologize. The rest of the group offers one guess each about what the person was like, and the player says yes or not quite and adds a sentence. Go around twice. Debrief on what it was like to speak of them in the present tense of a skill still in use, and on where in the week each player uses what they were taught. Keep turns short and let anyone pass. This works well mid-group, once members know each other’s losses.', '[{"id": "f0", "type": "textarea", "label": "The things the person I lost taught me:"}, {"id": "f1", "type": "textarea", "label": "What the group guessed about them, and what I added:"}, {"id": "f2", "type": "textarea", "label": "Where in my week I still use what they taught me:"}, {"id": "f3", "type": "textarea", "label": "What it was like to speak about them this way:"}, {"id": "f4", "type": "textarea", "label": "One thing I learned about someone else’s person that stayed with me:"}]'::jsonb, array['grief and loss', 'game', 'group']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('saying-their-name-out-loud-agreement-for-partners', 'Saying Their Name Out Loud Agreement for Partners', 'couples'::resource_kind, 'An agreement for couples who have lost someone about when and how the person’s name is spoken at home.', 'Use it to end the silence where one partner avoids the name to protect the other, who is longing to hear it.', array['Couples']::text[], '30 minutes', 'After a shared loss, one partner often stops saying the name to spare the other, while the other hears the silence as forgetting. Each describes what hearing the name does to them, on good days and bad. Then agree the rules of the house: the name is welcome at the table, there is a way to say not right now that is not a rebuke, and there is one time a week set aside for the person on purpose. Watch for the partner who grieves more privately being pushed into talk they do not want; the agreement should protect both styles. Revisit on anniversaries and when the rules stop fitting.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what hearing their name does to me, on a good day and on a hard one:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what hearing their name does to me, on a good day and on a hard one:"}, {"id": "f2", "type": "textarea", "label": "When and where the name is welcome in our home:"}, {"id": "f3", "type": "textarea", "label": "How either of us can say not right now without it being a rebuke:"}, {"id": "f4", "type": "textarea", "label": "The time each week we will set aside for them on purpose, and what we will do in it:"}]'::jsonb, array['grief and loss', 'couples', 'communication']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('laughing-again-means-forgetting-thought-check', 'Laughing Again Means Forgetting Thought Check', 'cbt'::resource_kind, 'A thought check for the guilt that follows the first laugh, the first good evening or the first day the loss was not the first thought.', 'Use it to help a grieving client separate a returning capacity for pleasure from the fear of forgetting the person.', array['Adults', 'Teens']::text[], '20 minutes', 'The first laugh after a loss often brings a second wave: guilt, and the thought that enjoying anything means the person is being left behind. Write the moment and the thought. Then look at the evidence: what did the client think about an hour later, what would the person who died have wanted, and does grief that returns after a laugh look like forgetting? Many clients find that the laugh and the grief sit side by side, and that the fear of forgetting is a sign of how much they remember. Finish by asking what the person would have said about the laugh.', '[{"id": "f0", "type": "textarea", "label": "The moment: what I laughed at or enjoyed, and the thought that came after:"}, {"id": "f1", "type": "textarea", "label": "What I was thinking about an hour later:"}, {"id": "f2", "type": "textarea", "label": "Whether grief that comes back after a laugh looks like forgetting, honestly:"}, {"id": "f3", "type": "textarea", "label": "What the person would have said about me laughing again:"}, {"id": "f4", "type": "textarea", "label": "A gentler sentence for the next time pleasure arrives:"}]'::jsonb, array['grief and loss', 'core CBT', 'thinking traps']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('estate-paperwork-pacing-sheet', 'Estate Paperwork Pacing Sheet', 'worksheet'::resource_kind, 'A pacing sheet for the accounts, forms and phone calls that follow a death, split into small sessions with support.', 'Use it to help a grieving client get through the administrative tasks of a loss without being flattened by them.', array['Adults']::text[], 'Several weeks', 'The paperwork after a death is relentless and each phone call means saying the words again. List every task the client knows of, then sort by deadline and by how much it hurts, since the two do not line up. Plan sessions of no more than an hour, with a support person present or on call for the hardest calls, and something gentle planned for afterward. Normalize the anger at institutions and the tears over a utility bill. Ask who could take over the tasks that do not need the client personally. Review each week; the aim is steady movement, not speed, and the client decides the pace.', '[{"id": "f0", "type": "textarea", "label": "Every task I know of: accounts, forms, calls, notifications:"}, {"id": "f1", "type": "textarea", "label": "Each one sorted by deadline, and separately by how much it hurts:"}, {"id": "f2", "type": "textarea", "label": "My next three one-hour sessions: which tasks, when, and who will be with me or on call:"}, {"id": "f3", "type": "textarea", "label": "What I will do for myself after each session:"}, {"id": "f4", "type": "textarea", "label": "Tasks someone else could take over, and who I will ask:"}, {"id": "f5", "type": "textarea", "label": "What I noticed after this week’s sessions:"}]'::jsonb, array['grief and loss', 'pacing', 'planning']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('sorry-steps-paper-footprints-craft', 'Sorry Steps Paper Footprints Craft', 'kids'::resource_kind, 'A child makes paper footprints for the steps of a real apology and walks them with a parent after a fight with a friend or sibling.', 'Use it to teach a child what a repair looks like step by step, with a parent walking it first.', array['Children']::text[], '30 minutes to make', 'Cut four or five large paper footprints and write a step on each with the child: say what I did, say how it might have felt for them, say sorry, ask what would help, do it. Decorate and keep them in a roll. After a fight, the child lays the path and walks it, saying each step aloud, before going to the other person. The parent walks the path themselves the first few times, apologizing for something real, so the child sees a grown-up do it. Keep the steps about the child’s own part; the path is not for extracting an apology from the other child.', '[{"id": "f0", "type": "textarea", "label": "My sorry steps, one on each footprint:"}, {"id": "f1", "type": "textarea", "label": "A time I walked the path this week, and who it was for:"}, {"id": "f2", "type": "textarea", "label": "The step that was hardest to say out loud:"}, {"id": "f3", "type": "textarea", "label": "What the other person said or did after:"}, {"id": "f4", "type": "textarea", "label": "Parent: the real apology I walked the path for, and what my child noticed:"}]'::jsonb, array['relationship issues', 'children', 'repair']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('validation-without-agreement-practice-card', 'Validation Without Agreement Practice Card', 'dbt'::resource_kind, 'A card for validating another person’s feelings or point of view while still holding a different position.', 'Use it to help a client stop treating validation as surrender and practice the both-at-once that keeps relationships intact.', array['Adults', 'Teens']::text[], '20 minutes, then live use', 'Many clients refuse to validate because they think it means agreeing. The card separates the two: find what is understandable in the other person’s reaction, say it plainly, and then state your own view without a but that erases the first half. Write three recent disagreements and draft both halves for each. Rehearse aloud, watching the tone of the second half. The usual discovery is that the other person softens once they feel understood, and the client’s view then gets heard. Pair with GIVE for the relationship side, or with DEAR MAN when the client also needs to ask for something.', '[{"id": "f0", "type": "textarea", "label": "Three recent disagreements where I would not validate because I did not agree:"}, {"id": "f1", "type": "textarea", "label": "For each: what is understandable in their reaction, said plainly:"}, {"id": "f2", "type": "textarea", "label": "For each: my own view, stated without erasing the first half:"}, {"id": "f3", "type": "textarea", "label": "A time this week I used both halves, and what the other person did:"}, {"id": "f4", "type": "textarea", "label": "What I notice about validating when I still disagree:"}]'::jsonb, array['relationship issues', 'core DBT', 'interpersonal effectiveness']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('love-as-a-verb-daily-actions-page', 'Love as a Verb Daily Actions Page', 'act'::resource_kind, 'A values page that turns the client’s wish to feel closer to someone into small daily actions they can do regardless of the feeling.', 'Use it to move a client from waiting to feel love or closeness to doing the things love does.', array['Adults', 'Teens']::text[], '20 minutes, then one week', 'Clients often wait for the feeling to return before acting, and the waiting widens the gap. Ask what love, friendship or closeness looks like as behavior in this relationship: the text sent, the question asked, the dish washed, the full attention given. Then pick three small actions for the week that the client will do whether or not the feeling shows up, with the feeling noticed and allowed to be whatever it is. Debrief on the actions and on what the other person did. This is not for relationships where the client’s safety is in question; attend to that first.', '[{"id": "f0", "type": "textarea", "label": "The relationship, and what I have been waiting to feel:"}, {"id": "f1", "type": "textarea", "label": "What love or closeness looks like as actions in this relationship, in plain behavior:"}, {"id": "f2", "type": "textarea", "label": "Three small actions for this week that I will do whatever the feeling does:"}, {"id": "f3", "type": "textarea", "label": "What I did, what the other person did, and what the feeling did, in separate columns:"}, {"id": "f4", "type": "textarea", "label": "What I notice about acting first:"}]'::jsonb, array['relationship issues', 'values', 'committed action']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('text-message-tone-misread-experiment-sheet', 'Text Message Tone Misread Experiment Sheet', 'cbt'::resource_kind, 'An experiment sheet for the tone a client reads into a short text and what the sender meant when asked.', 'Use it to test how reliably a client reads coldness or anger into texts and to build the habit of checking.', array['Adults', 'Teens']::text[], 'One week', 'A short reply, a missing emoji, a period at the end: clients read whole moods into them and respond to the mood they invented. Have them log texts that landed badly this week: the message, the tone they read, their confidence, and what they did. For two or three, with a safe sender, they ask what the sender meant or how they were feeling when they wrote it. Compare. Also have them look at their own short texts and ask what tone a reader might invent. Debrief on the pattern, and set a rule for the week: no replying to a tone, only to the words, until it is checked.', '[{"id": "f0", "type": "textarea", "label": "Texts this week that landed badly: the message, the tone I read, and how sure I was:"}, {"id": "f1", "type": "textarea", "label": "What I did in response to the tone I read:"}, {"id": "f2", "type": "textarea", "label": "For two or three: what the sender said they meant when I asked:"}, {"id": "f3", "type": "textarea", "label": "My own short texts this week, and the tone a reader could invent from them:"}, {"id": "f4", "type": "textarea", "label": "My rule for next week about replying to tone versus words:"}]'::jsonb, array['relationship issues', 'behavioral experiment', 'communication']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('one-sided-friendship-ledger-and-ask-sheet', 'One-Sided Friendship Ledger and Ask Sheet', 'worksheet'::resource_kind, 'A ledger for a friendship where the client does most of the reaching, listening and showing up, and a plan for one direct ask.', 'Use it to help a client see a lopsided friendship clearly and decide between asking for more, accepting it or stepping back.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask the client to list, for one friendship, who initiated, who listened and who showed up over the last two months, as factually as they can. Then ask what they have told themselves about the imbalance and what they have never said to the friend. Three honest options follow: make one direct ask, accept the friendship as it is at a smaller size, or step back. Draft the ask in plain words if that is the choice, and plan what the client will do with either answer. Watch for the client discounting their own needs or catastrophizing the ask. The friend’s side is unknown until it is asked.', '[{"id": "f0", "type": "textarea", "label": "Over the last two months: who initiated, who listened, who showed up, as factually as I can:"}, {"id": "f1", "type": "textarea", "label": "What I have told myself about the imbalance:"}, {"id": "f2", "type": "textarea", "label": "What I have never said to this friend:"}, {"id": "f3", "type": "textarea", "label": "My choice: one direct ask, accept it at a smaller size, or step back, and why:"}, {"id": "f4", "type": "textarea", "label": "If I ask: the plain words, and what I will do with a yes and with a no:"}]'::jsonb, array['relationship issues', 'boundaries', 'communication']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('heads-up-script-for-appointments-with-touch-sheet', 'Heads-Up Script for Appointments With Touch Sheet', 'worksheet'::resource_kind, 'A script sheet for telling a hairdresser, dentist, massage therapist or trainer what helps before an appointment that involves touch.', 'Use it to give a survivor a short, practiced way to set the terms of touch in everyday appointments without explaining why.', array['Adults', 'Teens']::text[], '20 minutes', 'Everyday appointments with touch can be hard for survivors, and many either avoid them or endure them. Build a two-sentence heads-up the client can say at the start: what they would like (tell me before you touch my neck, I may ask for a pause) without any account of why. Rehearse it aloud until it sounds ordinary. Plan the grounding they will use in the chair and the sign for a pause. Keep this entirely on the present and on what helps; it is not a space for recounting past events. Debrief afterward on how the provider responded, which is usually with easy agreement.', '[{"id": "f0", "type": "textarea", "label": "The appointment coming up, and what about it is hard, kept to the present:"}, {"id": "f1", "type": "textarea", "label": "My two-sentence heads-up, with no explanation of why:"}, {"id": "f2", "type": "textarea", "label": "My pause sign, and what I will do to ground myself in the chair:"}, {"id": "f3", "type": "textarea", "label": "Who I will tell afterward, if anyone:"}, {"id": "f4", "type": "textarea", "label": "How the provider responded, and what I will say next time:"}]'::jsonb, array['sexual abuse', 'safety', 'self-advocacy']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('eyes-open-breath-count-grounding-card', 'Eyes Open Breath Count Grounding Card', 'dbt'::resource_kind, 'A grounding card for counting breaths with eyes open and fixed on a point in the room, for clients who cannot safely close their eyes.', 'Use it to give a survivor a mindfulness practice that keeps the room in view and the body anchored.', array['Adults', 'Teens']::text[], 'Three minutes, as needed', 'Many standard breathing practices begin with closed eyes, which for some survivors removes the very thing that keeps them steady: seeing the room. This card keeps the eyes open, resting on a chosen point, and counts the out-breaths to ten and back to one, with a pre-chosen anchor phrase for when attention drifts. Practice in session first with the client choosing the point and the phrase. Teach the parent, partner or support person to sit alongside silently if the client wants that. Stop if distress rises rather than pushing through, and keep the frame on present safety and steadiness.', '[{"id": "f0", "type": "textarea", "label": "The point in the room I will rest my eyes on:"}, {"id": "f1", "type": "textarea", "label": "My anchor phrase for when my attention drifts:"}, {"id": "f2", "type": "textarea", "label": "What my body noticed by the count of ten:"}, {"id": "f3", "type": "textarea", "label": "A moment this week I used the card, and where I was:"}, {"id": "f4", "type": "textarea", "label": "What I want my support person to do, or not do, if they are beside me:"}]'::jsonb, array['sexual abuse', 'grounding', 'core DBT']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('everyone-can-tell-by-looking-thought-check-sheet', 'Everyone Can Tell by Looking Thought Check Sheet', 'cbt'::resource_kind, 'A gentle thought check for the belief that strangers can see what happened just by looking at the client.', 'Use it to help a survivor examine the feeling of being marked and separate it from what people can actually see.', array['Adults', 'Teens']::text[], '20 minutes in session', 'The sense of being visibly marked is common and painful, and it keeps clients out of rooms. Write the thought as it sounds, and what the client believes people see. Then ask gently: what do they know about the strangers around them, what have those people actually said or done, and what does the client see when they look at other survivors they know? Keep the work on the present-day belief and never on the events behind it. Complete this in session, go at the client’s pace, and stop if the feeling of being marked turns into shame that needs tending first.', '[{"id": "f0", "type": "textarea", "label": "The thought, as it sounds: when people look at me they can see:"}, {"id": "f1", "type": "textarea", "label": "What I know about the strangers I have passed this week, and what they have actually said or done:"}, {"id": "f2", "type": "textarea", "label": "What I see when I look at other people who have been through hard things:"}, {"id": "f3", "type": "textarea", "label": "A gentler sentence about what people actually see:"}, {"id": "f4", "type": "textarea", "label": "One room I am willing to walk into this week, and what I will hold onto there:"}]'::jsonb, array['sexual abuse', 'core CBT', 'self-compassion']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('comfort-basket-soft-things-build', 'Comfort Basket Soft Things Build', 'kids'::resource_kind, 'A child and a trusted adult fill a basket with soft, soothing things the child chooses, to use whenever they need to feel safe.', 'Use it to give a child a sensory safe-feeling kit built with a trusted adult, with nothing in it about what happened.', array['Children']::text[], '30 minutes', 'Bring a basket and let the child choose from soft fabrics, a stuffed animal, a smooth stone, a small blanket, a picture of a safe person, a favorite scent on a cloth. The adult asks what each thing feels like, not why the child wants it. Agree where the basket lives and that the child can go to it any time without asking. Coach the adult to sit nearby quietly when the child uses it. Keep every part of this on comfort in the present; do not ask the child about past events. If the child discloses abuse during the build, follow your reporting duties and keep your response calm and believing.', '[{"id": "f0", "type": "textarea", "label": "The things I chose for my basket:"}, {"id": "f1", "type": "textarea", "label": "What each one feels like in my hands or smells like:"}, {"id": "f2", "type": "textarea", "label": "Where my basket lives, and who knows I can use it any time:"}, {"id": "f3", "type": "textarea", "label": "A time I used it this week, and what helped most:"}, {"id": "f4", "type": "textarea", "label": "Trusted adult: how I sat nearby, and what my child added or took out:"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('yes-maybe-not-now-touch-menu-for-partners', 'Yes Maybe Not Now Touch Menu for Partners', 'couples'::resource_kind, 'A menu of specific kinds of touch that a survivor sorts into yes, maybe and not now, shared with a partner who agrees to follow it.', 'Use it to give a couple a concrete, revisable map of welcome touch so neither has to guess or endure.', array['Couples']::text[], '45 minutes', 'Many couples after sexual trauma fall into either no touch at all or touch the survivor endures. The menu lists specific, everyday kinds of touch: hand held, hug from the front, head on shoulder, back rubbed, and so on, with the survivor sorting each into yes, maybe and not now, in private first. The partner reads it and agrees to follow it without negotiation, and to ask before any maybe. Keep the exercise entirely on the present and on what feels okay, and never on the history. Check that the partner has their own support, since following the menu patiently can be hard for them too.', '[{"id": "f0", "type": "textarea", "label": "Partner who sorted: my yes list, kinds of touch that are welcome without asking:"}, {"id": "f1", "type": "textarea", "label": "Partner who sorted: my maybe list, kinds of touch to ask about first:"}, {"id": "f2", "type": "textarea", "label": "Partner who sorted: my not now list, with no explanation needed:"}, {"id": "f3", "type": "textarea", "label": "Supporting partner: what I agree to, and what I will do when I am unsure:"}, {"id": "f4", "type": "textarea", "label": "Both: our review date, and how either of us can ask to talk about the menu before then:"}]'::jsonb, array['sexual abuse', 'couples', 'boundaries']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('skill-scattergories-letter-round-game', 'Skill Scattergories Letter Round Game', 'game'::resource_kind, 'A category game where players race to name a coping skill, a calming place, a kind word and a helper that all start with the called letter.', 'Use it to get a group generating coping ideas quickly and playfully, and to borrow from each other’s lists.', array['Groups', 'Teens', 'Children']::text[], '25 minutes', 'Rules: call a letter. In ninety seconds each player writes one answer per category that starts with it: a coping skill, a calming place, a kind thing to say to yourself, a person or animal who helps. Answers nobody else wrote score two points; shared answers score one. Play four or five letters. Debrief by having each player circle two skills from other people’s lists that they want to try, and one from their own list that they forgot they had. Keep a running group list on the wall. Children may draw instead of write.', '[{"id": "f0", "type": "textarea", "label": "My answers for each letter we played:"}, {"id": "f1", "type": "textarea", "label": "The answers that scored double because nobody else had them:"}, {"id": "f2", "type": "textarea", "label": "Two skills from other people’s lists I want to try:"}, {"id": "f3", "type": "textarea", "label": "One skill on my own list I had forgotten I had:"}, {"id": "f4", "type": "textarea", "label": "When this week I will try one of the borrowed skills:"}]'::jsonb, array['coping skills', 'game', 'group']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('coping-cube-dice-craft', 'Coping Cube Dice Craft', 'kids'::resource_kind, 'A child builds a paper cube with a different calming move on each face and rolls it when they need help choosing.', 'Use it to give a child who freezes when upset a way to pick a coping move by chance, with a parent rolling alongside.', array['Children']::text[], '30 minutes to make', 'Print or draw a cube template. The child picks six calming moves they already know a little, such as big breaths, squeeze and release, get a drink of water, find a grown-up, draw it, jump ten times, and draws one on each face. Fold and tape. When upset, the child rolls and does what the cube says, and the parent does it too. Rolling removes the hardest part, which is choosing while flooded. Practice in calm moments so the moves are familiar. Replace a face that never helps. Siblings can each have their own cube, and a family cube can live in the kitchen.', '[{"id": "f0", "type": "textarea", "label": "The six moves on my cube:"}, {"id": "f1", "type": "textarea", "label": "A time I rolled it this week, what it said, and whether it helped:"}, {"id": "f2", "type": "textarea", "label": "The face I want to change, and what I will put instead:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up did when I rolled:"}, {"id": "f4", "type": "textarea", "label": "Parent: how the practice rolls went in calm moments, and what I noticed in a real one:"}]'::jsonb, array['coping skills', 'children', 'craft']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('self-soothe-sound-menu-card', 'Self-Soothe Sound Menu Card', 'dbt'::resource_kind, 'A self-soothe card built around hearing alone: the specific sounds, songs and voices that settle this client.', 'Use it to give a client a ready list of sounds to reach for when the other senses are too much or unavailable.', array['Adults', 'Teens']::text[], '15 minutes to build, then as needed', 'The hearing part of self-soothe often gets a single generic line, calming music, and is never used. Build it properly: three songs with names, a nature sound, a voice recording of someone kind, a podcast that asks nothing, the sound of a particular room. Set each one up so it is one tap away at the moments it will be needed, including the car and the bedroom. Ask the client to notice which sounds settle the body and which only distract the mind, and keep both but label them. Review after a week and prune anything that was never used.', '[{"id": "f0", "type": "textarea", "label": "Three songs with names, and when each one helps:"}, {"id": "f1", "type": "textarea", "label": "A nature sound, a kind voice I could record, a podcast that asks nothing of me:"}, {"id": "f2", "type": "textarea", "label": "The sounds that settle my body, and the ones that only distract my mind:"}, {"id": "f3", "type": "textarea", "label": "Where each one is one tap away: phone, car, bedroom:"}, {"id": "f4", "type": "textarea", "label": "After a week: what I used, what I never touched, and what I will add:"}]'::jsonb, array['coping skills', 'core DBT', 'distress tolerance']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('changeable-or-not-stressor-sort-sheet', 'Changeable or Not Stressor Sort Sheet', 'cbt'::resource_kind, 'A sorting sheet that splits the week’s stressors into ones to change and ones to cope with, and matches a skill to each.', 'Use it to stop a client problem-solving the unchangeable and enduring the changeable.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients often apply the wrong tool: endless planning for a stressor nothing can change, and gritted teeth for one that a single phone call would fix. List the week’s stressors. For each, ask what part is within the client’s control. Changeable parts get a concrete next step with a day attached. Unchangeable parts get a coping move: acceptance practice, a self-soothe plan, a support person. Watch for the client sorting everything into unchangeable out of hopelessness or everything into changeable out of over-responsibility; both patterns are worth naming.', '[{"id": "f0", "type": "textarea", "label": "This week’s stressors, as a list:"}, {"id": "f1", "type": "textarea", "label": "For each: the part I can change, and the part I cannot:"}, {"id": "f2", "type": "textarea", "label": "A concrete next step for each changeable part, with a day:"}, {"id": "f3", "type": "textarea", "label": "A coping move for each unchangeable part:"}, {"id": "f4", "type": "textarea", "label": "Which way I tend to over-sort, toward changeable or toward unchangeable, and what that costs me:"}]'::jsonb, array['coping skills', 'core CBT', 'planning']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('coping-skills-by-location-map', 'Coping Skills by Location Map', 'worksheet'::resource_kind, 'A map of where the client’s hard moments happen, with the coping skill that is actually possible in each place.', 'Use it to match coping skills to the car, the desk, the bathroom at work and the bed, where the generic list fails.', array['Adults', 'Teens']::text[], '25 minutes', 'A skill that needs a yoga mat is useless in a staff meeting. Have the client list the places their hard moments happen, then, for each, what is actually possible there: what can be done in a bathroom stall, in traffic, at a desk with people watching, lying awake. Match a skill to each place, and plan any setup the place needs, such as a card in the glovebox or a note in the phone. Review after a week for the places that still had nothing, which are usually where the client feels most trapped. Public places often need skills that are invisible; name a few.', '[{"id": "f0", "type": "textarea", "label": "The places where my hard moments happen:"}, {"id": "f1", "type": "textarea", "label": "For each place: what I can realistically do there without being noticed:"}, {"id": "f2", "type": "textarea", "label": "The skill I will match to each place, and any setup it needs:"}, {"id": "f3", "type": "textarea", "label": "After a week: which places still had nothing that worked:"}, {"id": "f4", "type": "textarea", "label": "An invisible skill for the most public of my places:"}]'::jsonb, array['coping skills', 'planning', 'self-monitoring']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('fear-step-celebration-plan-for-partners', 'Fear Step Celebration Plan for Partners', 'couples'::resource_kind, 'A plan for how a couple will mark each step the fearful partner takes, agreed in advance so the celebration lands.', 'Use it to make a partner’s support a steady reward for approach rather than a reaction only to the big day.', array['Couples']::text[], '30 minutes', 'Supportive partners often wait to celebrate the final step, such as the flight or the dentist, and either overdo it or miss the dozens of small steps before. The fearful partner says what kind of recognition actually feels good and what feels like pressure or fuss. The supporting partner agrees a specific small marker for every step, from a text to a shared dessert, and a rule about not grading the steps. Also agree what will be said when a step does not happen, so the plan does not become a new source of shame. Review the plan as the ladder progresses.', '[{"id": "f0", "type": "textarea", "label": "Fearful partner: the recognition that feels good to me, and what feels like pressure:"}, {"id": "f1", "type": "textarea", "label": "Supporting partner: how I usually react to a step, and what I tend to miss:"}, {"id": "f2", "type": "textarea", "label": "Our marker for each small step, and the rule about not grading them:"}, {"id": "f3", "type": "textarea", "label": "What we will each say when a planned step does not happen:"}, {"id": "f4", "type": "textarea", "label": "The next step on the ladder, and how we will mark it:"}]'::jsonb, array['phobias', 'couples', 'support']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('dark-room-flashlight-treasure-hunt-play', 'Dark Room Flashlight Treasure Hunt Play', 'kids'::resource_kind, 'A parent hides small treasures in a dim room and the child hunts for them with a flashlight, with the light dimming over the week.', 'Use it to help a child afraid of the dark build comfort in low light through play they control.', array['Children']::text[], '15 minutes an evening for a week', 'Start with the room lights low rather than off, a flashlight the child holds, and five treasures to find. The child controls the light and can stop whenever they want. Each evening, dim the room a little more and let the child choose whether to go on. The parent stays in the room, speaks in a normal voice and does not use the game to argue that the dark is safe; the child’s own experience does that. Keep a tally of treasures found. Children often ask to turn the lights down themselves by the end of the week. Praise the choosing, not the bravery.', '[{"id": "f0", "type": "textarea", "label": "How bright the room was tonight, and whether I chose to dim it:"}, {"id": "f1", "type": "textarea", "label": "The treasures I found:"}, {"id": "f2", "type": "textarea", "label": "What my body felt like at the start and at the end:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up did while I hunted:"}, {"id": "f4", "type": "textarea", "label": "Parent: how I kept my voice normal, and what my child chose about the lights:"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('thunderstorm-facts-versus-feelings-sheet', 'Thunderstorm Facts Versus Feelings Sheet', 'cbt'::resource_kind, 'A two-column sheet for a storm-fearful client separating what they feel during thunder from what is observably happening.', 'Use it to help a client who hides from storms notice how far the fear outruns the facts and plan to stay in the room.', array['Adults', 'Teens', 'Children']::text[], '20 minutes, then during the next storm', 'During a storm the body goes to full alarm, and the mind supplies a catastrophe to match. Before the next storm, have the client write what they predict will happen and how they usually behave. During the storm, with the sheet to hand, they write in two columns what they feel and what is observably true: thunder, rain on the window, lights on, house standing. Afterward they compare the prediction with what happened. Pair with a small step, such as staying in a lit room with a window instead of the closet. For children, the parent fills the facts column alongside them.', '[{"id": "f0", "type": "textarea", "label": "What I predict will happen in the next storm, and what I usually do:"}, {"id": "f1", "type": "textarea", "label": "During the storm, feelings column: what my body and mind are doing:"}, {"id": "f2", "type": "textarea", "label": "During the storm, facts column: what is observably happening around me:"}, {"id": "f3", "type": "textarea", "label": "Afterward: what actually happened, compared with my prediction:"}, {"id": "f4", "type": "textarea", "label": "My step for the next storm, one notch toward staying in the room:"}]'::jsonb, array['phobias', 'core CBT', 'exposure']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('feeling-queasy-willingness-page', 'Feeling Queasy Willingness Page', 'act'::resource_kind, 'A willingness page for the client whose fear of feeling or being sick has shrunk their eating out, travel and social life.', 'Use it to help a client make room for queasiness as a sensation while moving toward the life the fear has narrowed.', array['Adults', 'Teens']::text[], '25 minutes', 'Fear of nausea or of being sick in public leads to a quiet, severe narrowing: no restaurants, no long drives, no crowded rooms. Map the narrowing without judgment. Then explore what the client does when queasiness arrives: scan, sip, leave, cancel. Introduce willingness as allowing the sensation to be there while choosing an action, and pick one small step, such as a short drive without an escape plan, done with the sensation allowed. Debrief on what the sensation did when it was not fought. Keep well away from food rules of any kind; this is about the sensation, not what is eaten.', '[{"id": "f0", "type": "textarea", "label": "Where the fear of feeling sick has narrowed my life:"}, {"id": "f1", "type": "textarea", "label": "What I do when queasiness arrives: scan, sip, leave, cancel, or something else:"}, {"id": "f2", "type": "textarea", "label": "What the narrowing has cost me in what I care about:"}, {"id": "f3", "type": "textarea", "label": "One small step this week with the sensation allowed to come along:"}, {"id": "f4", "type": "textarea", "label": "What the sensation did when I stopped fighting it:"}]'::jsonb, array['phobias', 'willingness', 'acceptance']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('observe-and-describe-the-feared-object-card', 'Observe and Describe the Feared Object Card', 'dbt'::resource_kind, 'A mindfulness card for looking at a feared object or picture and describing only what is observed, in neutral words.', 'Use it to give a client a way to stay with a feared thing by narrating its observable features rather than its danger.', array['Adults', 'Teens', 'Children']::text[], 'Five minutes, repeated', 'From the mindfulness what skills: observe and describe. With a picture or a safe real example of the feared thing, the client describes aloud only what can be seen: color, size, number of legs, how it moves, where it is. Judgments and predictions get caught and set aside with a word. Start at a distance the client chooses and hold each round to a minute or two. The describing occupies the mind that would otherwise forecast, and the client often notices the thing is smaller or stiller than remembered. Children can do this with a parent describing alongside.', '[{"id": "f0", "type": "textarea", "label": "The object or picture, and the distance I chose:"}, {"id": "f1", "type": "textarea", "label": "What I observed, in neutral words only:"}, {"id": "f2", "type": "textarea", "label": "The judgments and predictions I caught and set aside:"}, {"id": "f3", "type": "textarea", "label": "How my body changed between the first minute and the last:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the thing that my memory had gotten wrong:"}]'::jsonb, array['phobias', 'core DBT', 'mindfulness']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('non-looks-compliment-sticky-note-back-game', 'Non-Looks Compliment Sticky Note Back Game', 'game'::resource_kind, 'Players stick notes on each other’s backs with compliments that have nothing to do with appearance, then read their own aloud.', 'Use it to flood a group with compliments about who people are and let each member hear theirs read out.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Rules: everyone gets a pad of sticky notes. For ten minutes, players mingle and stick a compliment on each person’s back; nothing about appearance, clothes or body is allowed, and a looks compliment is removed by the leader. Then each player peels their notes off and reads them aloud, one at a time, without commentary. Debrief on what it was like to receive compliments that had nothing to do with looks, which ones were hardest to read aloud, and how much of the group’s usual compliment traffic is about appearance. Players keep their notes.', '[{"id": "f0", "type": "textarea", "label": "The notes I found on my back:"}, {"id": "f1", "type": "textarea", "label": "The one that was hardest to read aloud, and why:"}, {"id": "f2", "type": "textarea", "label": "What I wrote on other people, and whether I had to resist a looks compliment:"}, {"id": "f3", "type": "textarea", "label": "How much of the compliment traffic in my life is about appearance, roughly:"}, {"id": "f4", "type": "textarea", "label": "One non-looks compliment I will give someone this week:"}]'::jsonb, array['body image', 'game', 'strengths']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('funny-faces-mirror-play', 'Funny Faces Mirror Play', 'kids'::resource_kind, 'A child and parent make the silliest faces they can in a mirror together, turning the mirror into a place for play rather than inspection.', 'Use it to give a child, and a parent, a mirror habit that is about what faces can do instead of how they look.', array['Children']::text[], '10 minutes, daily for a week', 'Stand at a mirror together and take turns: the widest eyes, the fish mouth, the surprised eyebrows, the monster. The other copies. Add voices. The only rule is that nobody says anything about how anyone looks, good or bad; the mirror is for what faces can do. Parents matter here more than children: coach the parent to watch their own mirror talk all week, since children learn to inspect from watching adults inspect. Debrief on what the child’s face can do and what the parent noticed about their own habits. Keep it short and silly, and stop before it gets tired.', '[{"id": "f0", "type": "textarea", "label": "The faces I can make, and my favorite:"}, {"id": "f1", "type": "textarea", "label": "The face my grown-up made that made me laugh most:"}, {"id": "f2", "type": "textarea", "label": "What faces are for, in my own words:"}, {"id": "f3", "type": "textarea", "label": "A time this week I looked in a mirror and made a face instead of checking:"}, {"id": "f4", "type": "textarea", "label": "Parent: what I noticed about my own mirror talk this week:"}]'::jsonb, array['body image', 'children', 'play']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('bad-hair-day-ruins-everything-forecast-sheet', 'Bad Hair Day Ruins Everything Forecast Sheet', 'cbt'::resource_kind, 'A prediction sheet testing the belief that an appearance mishap in the morning will wreck the whole day.', 'Use it to help a client check how much a bad hair day, a blemish or a wrinkled shirt actually changes what happens.', array['Adults', 'Teens']::text[], 'Several mornings', 'On a morning the client feels something is wrong with how they look, have them write the forecast: what people will notice, what will go badly, how the day will rate. Then they go through the day and record what people said, what went badly and whether it was connected, and the day’s actual rating. Over several mornings the gap between forecast and outcome becomes the data. Watch for the client fixing the problem before leaving, which cancels the test; the experiment is to go as they are. Never bring body shape or size into the sheet; keep it to the mishap and the forecast.', '[{"id": "f0", "type": "textarea", "label": "What felt wrong about how I looked this morning:"}, {"id": "f1", "type": "textarea", "label": "My forecast: who will notice, what will go badly, and how the day will rate:"}, {"id": "f2", "type": "textarea", "label": "What people actually said or did about it, if anything:"}, {"id": "f3", "type": "textarea", "label": "What went badly today, and whether it was connected:"}, {"id": "f4", "type": "textarea", "label": "The day’s actual rating next to the forecast, and my running record across mornings:"}]'::jsonb, array['body image', 'behavioral experiment', 'core CBT']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('changing-face-over-time-willingness-page', 'Changing Face Over Time Willingness Page', 'act'::resource_kind, 'A willingness page for the client distressed by seeing their face age, with values the face has been present for.', 'Use it to help a client make room for an aging face and reconnect with what the years in it were spent on.', array['Adults']::text[], '25 minutes', 'Ask what the client sees and what the mind says about it, and write it without correction. Then ask what the face has been present for: the people it has smiled at, the losses it has cried through, the work it has frowned over. Explore what fighting the change costs in time, money and attention, and what willingness would look like: the mirror glanced at and left, the photo kept rather than deleted. Keep away from any talk of procedures or products; the clinician’s lane is the relationship with the change, not the change itself.', '[{"id": "f0", "type": "textarea", "label": "What I see when I look at my face now, and what my mind says about it:"}, {"id": "f1", "type": "textarea", "label": "What this face has been present for: the people, the losses, the work:"}, {"id": "f2", "type": "textarea", "label": "What fighting the change costs me in time, money and attention:"}, {"id": "f3", "type": "textarea", "label": "What willingness would look like this week: the mirror, the photos, the conversation I avoid:"}, {"id": "f4", "type": "textarea", "label": "One thing my face did this week that mattered more than how it looked:"}]'::jsonb, array['body image', 'willingness', 'values']::text[], '2026-11-14T15:00:00+00:00'::timestamptz),
  ('wise-mind-before-posting-a-photo-card', 'Wise Mind Before Posting a Photo Card', 'dbt'::resource_kind, 'A wise mind pause card for the moment before posting, editing or deleting a photo of oneself.', 'Use it to help a client notice emotion mind and reasonable mind at the posting moment and choose from wise mind instead.', array['Teens', 'Adults']::text[], 'Two minutes, at the moment of posting', 'The posting moment is a reliable trigger: the photo is taken, edited, compared, posted, checked and often deleted. The card asks three questions in sequence: what is emotion mind saying, what is reasonable mind saying, and what would wise mind do with this photo right now? Options include posting as is, posting with no edits, not posting and keeping, and putting the phone down for ten minutes. Have the client track a week of posting moments and the choice made. Keep away from the content of the photo and from the body in it; the card is about the mind states at the moment of choice.', '[{"id": "f0", "type": "textarea", "label": "The posting moment: what emotion mind was saying:"}, {"id": "f1", "type": "textarea", "label": "What reasonable mind was saying:"}, {"id": "f2", "type": "textarea", "label": "What wise mind chose, and what I actually did:"}, {"id": "f3", "type": "textarea", "label": "My week of posting moments, and the choice made at each:"}, {"id": "f4", "type": "textarea", "label": "What I notice about the moments when I waited ten minutes:"}]'::jsonb, array['body image', 'core DBT', 'wise mind']::text[], '2026-11-14T15:00:00+00:00'::timestamptz)
